export const c11Phy7HtmlOverview = "<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n\n  <!-- CHAPTER TITLE BANNER -->\n  <div style=\"background: rgba(255, 0, 127, 0.05); border: 1.5px solid #FF007F; border-radius: 12px; padding: 18px; margin-bottom: 25px; text-align: center;\">\n    <h1 style=\"color: #FF007F; margin: 0 0 6px 0; font-size: 24px; font-weight: bold; text-align: center !important;\">\n      Unit VII: Properties of Bulk Matter (09 Marks)\n    </h1>\n    <p style=\"color: #CBD5E1; margin: 0; font-size: 15px; text-align: center !important;\">\n      Comprehensive Reference Textbook Guide &bull; JKBOSE / CBSE Official Syllabus Alignment\n    </p>\n  </div>\n\n  <!-- QUICK GLOSSARY & BASIC DEFINITIONS CARD -->\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 0, 127, 0.3); border-radius: 10px; padding: 16px; margin-bottom: 25px;\">\n    <h3 style=\"color: #FF007F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">\n      ⚡ Quick Glossary & Fundamental Material Coefficients\n    </h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 12px; font-size: 14px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF007F; border-radius: 4px;\">\n        <b style=\"color: #FF007F;\">Young&apos;s Modulus (Y):</b> Ratio of longitudinal stress to longitudinal strain within elastic limit; Y = (F L / A &Delta;L). SI Unit: <b>N/m<sup>2</sup> (Pa)</b> &bull; Dimensions: <b>[M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</b>.\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF007F; border-radius: 4px;\">\n        <b style=\"color: #FF007F;\">Coefficient of Viscosity (&eta;):</b> Tangential viscous force per unit area per unit velocity gradient; &eta; = (F / A(dv/dx)). SI Unit: <b>Pa s (Poiseuille)</b> &bull; Dimensions: <b>[M<sup>1</sup> L<sup>-1</sup> T<sup>-1</sup>]</b>.\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF007F; border-radius: 4px;\">\n        <b style=\"color: #FF007F;\">Surface Tension (T):</b> Force per unit length acting perpendicular to an imaginary line drawn on a liquid surface; T = F/L = W/&Delta;A. SI Unit: <b>N/m (or J/m<sup>2</sup>)</b> &bull; Dimensions: <b>[M<sup>1</sup> L<sup>0</sup> T<sup>-2</sup>]</b>.\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; border-radius: 4px;\">\n        <b style=\"color: #FF007F;\">Thermal Conductivity (K):</b> Heat energy conducted per second across unit area per unit temperature gradient; K = (Q d / A &Delta;T t). SI Unit: <b>W m<sup>-1</sup> K<sup>-1</sup></b> &bull; Dimensions: <b>[M<sup>1</sup> L<sup>1</sup> T<sup>-3</sup> K<sup>-1</sup>]</b>.\n      </div>\n    </div>\n  </div>\n\n  <!-- ========================================== -->\n  <!-- PART 1: MECHANICAL PROPERTIES OF SOLIDS   -->\n  <!-- ========================================== -->\n  <div style=\"background: rgba(255, 0, 127, 0.08); border-left: 4px solid #FF007F; padding: 10px 16px; margin: 30px 0 15px 0; border-radius: 0 6px 6px 0;\">\n    <h2 style=\"color: #FF007F; margin: 0; font-size: 20px; font-weight: bold;\">\n      PART 1: Mechanical Properties of Solids\n    </h2>\n  </div>\n\n  <h3 style=\"color: #FF007F; margin-top: 20px;\">\n    1. Elasticity, Stress, Strain & Hooke&apos;s Law\n  </h3>\n  <p>\n    In a microscopic solid lattice, constituent atoms or molecules occupy stable equilibrium positions where interatomic attractive and repulsive forces precisely balance. When an external deforming force is applied, atoms are displaced from their equilibrium sites, eliciting internal restoring forces. Upon removal of the deforming load, these internal forces restore the original lattice geometry. The property by virtue of which a material regains its original shape and size after deforming forces are removed is termed <b>Elasticity</b>.\n  </p>\n\n  <p>\n    <b style=\"color: #FF007F;\">(i) Stress and Its Classifications:</b><br/>\n    Stress is defined as the internal restoring force developed per unit cross-sectional area of the deformed body: Stress = F_{res} / A.\n    <br/>&bull; <b>Longitudinal Stress:</b> Deforming force acts normal to the cross-sectional area, causing a change in length (Tensile stress causes elongation; Compressive stress causes shortening).\n    <br/>&bull; <b>Volume (Hydraulic) Stress:</b> A uniform external pressure acts perpendicular to every point on the surface of a body submerged in a fluid, altering volume without altering geometric shape: \\sigma_v = &Delta;P.\n    <br/>&bull; <b>Shearing (Tangential) Stress:</b> Deforming force is applied parallel to the surface, causing angular deformation (shear) without volume alteration: &tau; = F_{\\parallel} / A.\n  </p>\n\n  <p>\n    <b style=\"color: #FF007F;\">(ii) Strain and Its Classifications:</b><br/>\n    Strain is the dimensionless fractional deformation produced in the body: Strain = (Change in dimension / Original dimension).\n    <br/>&bull; <b>Longitudinal Strain:</b> \\epsilon = (&Delta;L / L).\n    <br/>&bull; <b>Volume Strain:</b> \\theta_v = (&Delta;V / V).\n    <br/>&bull; <b>Shear Strain:</b> &theta; = (&Delta;x / L) = \\tan&theta; &approx; &theta; (in radians).\n  </p>\n\n  \n  <div style=\"background: rgba(255, 0, 127, 0.06); border: 1.5px solid #FF007F; border-radius: 10px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 6px;\">\n      <span style=\"background: #FF007F; color: #FFFFFF; font-weight: bold; font-size: 11px; padding: 2px 8px; border-radius: 4px; text-transform: uppercase; letter-spacing: 0.5px;\">DEFINITION</span>\n      <b style=\"color: #FF007F; font-size: 16px;\">Hooke's Law</b>\n    </div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">Within the proportional elastic limit of a material, the stress developed is directly proportional to the strain produced: Stress = E &times; Strain, where E is the Modulus of Elasticity of the material.</div>\n    \n    <div style=\"display: flex; gap: 16px; margin-top: 10px; padding-top: 8px; border-top: 1px dashed rgba(255, 0, 127, 0.3); font-size: 13.5px; color: #CBD5E1;\">\n      <span><b>SI Unit:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">N/m<sup>2</sup> (Pascal, Pa)</code></span>\n      <span><b>Dimensional Formula:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">[M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</code></span>\n    </div>\n  </div>\n\n  <p>\n    <b style=\"color: #FF007F;\">(iii) Stress-Strain Curve for a Metallic Wire:</b><br/>\n    When a uniform metallic wire (such as structural steel) is subjected to progressively increasing tensile loads, its deformation traces a characteristic path:\n    <br/>1. <b>Region OA (Proportionality Limit):</b> Stress is strictly linear with strain, obeying Hooke&apos;s law exactly. Slope equals Young&apos;s modulus Y.\n    <br/>2. <b>Region AB (Elastic Limit / Yield Point B):</b> The curve bends slightly. Hooke&apos;s law is no longer strictly obeyed, but upon removing the load, the wire returns completely along BO to its original length. The stress corresponding to point B is the <b>Yield Strength</b> (sigma_y).\n    <br/>3. <b>Region BC (Plastic Deformation & Permanent Set):</b> Beyond point B, even a small increase in stress induces large elongation. If unloaded at point C, the wire does not retrace BO; it contracts along the dashed line, leaving a <b>permanent strain (permanent set)</b>.\n    <br/>4. <b>Point D (Ultimate Tensile Strength):</b> The maximum stress the material can sustain without necking. Beyond D, localized thinning (&apos;necking&apos;) occurs.\n    <br/>5. <b>Point E (Fracture / Breaking Point):</b> The wire ruptures. Materials with a wide plastic region between B and E are <b>ductile</b> (copper, mild steel); materials where fracture occurs immediately beyond the elastic limit are <b>brittle</b> (glass, cast iron); substances showing large elastic strains without a distinct plastic range are <b>elastomers</b> (rubber, aortic tissue).\n  </p>\n\n  <h3 style=\"color: #FF007F; margin-top: 20px;\">\n    2. Elastic Moduli, Poisson&apos;s Ratio & Elastic Potential Energy\n  </h3>\n  <p>\n    <b style=\"color: #FF007F;\">(i) Young&apos;s Modulus (Y):</b> Longitudinal stress divided by longitudinal strain:\n    $Y = (F / A / &Delta;L / L) = (F L / A &Delta;L) = (M g L / &pi; r<sup>2</sup> &Delta;L)\n    <br/><b style=\"color: #FF007F;\">(ii) Bulk Modulus (B):</b> Volume stress divided by volumetric strain:\n    B = -(&Delta;P / &Delta;V / V) = -V (&Delta;P / &Delta;V)\n    The negative sign ensures B is positive, since an increase in pressure produces a decrease in volume. The reciprocal of Bulk Modulus is termed <b>Compressibility</b>: k = 1/B.\n    <br/><b style=\"color: #FF007F;\">(iii) Shear Modulus of Rigidity (&eta;):</b> Tangential stress divided by shearing strain:\n    &eta; = {F_{\\parallel} / A}{&theta;}\n    <br/><b style=\"color: #FF007F;\">(iv) Poisson&apos;s Ratio (&sigma;):</b> When a wire elongates, its lateral diameter contracts. Poisson&apos;s ratio is the ratio of lateral strain to longitudinal strain:\n    &sigma; = (Lateral Strain / Longitudinal Strain) = -(&Delta;d / d / &Delta;L / L)\n    Theoretical limits for isotropic solids: -1 &le; &sigma; &le; 0.5 (practical values for metals lie between 0.25 and 0.35; for incompressible rubber, &sigma; &approx; 0.5).\n  </p>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.3); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 14px; border-bottom: 1px solid rgba(255, 0, 127, 0.2); padding-bottom: 8px;\">\n      <span style=\"color: #FF007F; font-size: 18px;\">📐</span>\n      <b style=\"color: #FF007F; font-size: 15.5px;\">Derivation of Elastic Potential Energy in a Stretched Wire</b>\n    </div>\n    \n    <div style=\"display: flex; gap: 12px; margin-bottom: 12px; align-items: flex-start;\">\n      <span style=\"background: rgba(255, 0, 127, 0.2); color: #FF007F; font-weight: bold; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 12px; border: 1px solid #FF007F;\">1</span>\n      <div style=\"flex: 1;\">\n        <div style=\"color: #FF007F; font-weight: 600; font-size: 14px; margin-bottom: 2px;\">Work Done in Infinitesimal Elongation</div>\n        <div style=\"color: #E2E8F0; font-size: 14px; line-height: 1.5;\">When a wire of original length L and area A is stretched by extension x, the restoring tension is: F = (Y A / L) x Work done by the stretching force in producing an additional extension dx: dW = F\\,dx = ((Y A / L) x) dx</div>\n      </div>\n    </div>\n  \n    <div style=\"display: flex; gap: 12px; margin-bottom: 12px; align-items: flex-start;\">\n      <span style=\"background: rgba(255, 0, 127, 0.2); color: #FF007F; font-weight: bold; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 12px; border: 1px solid #FF007F;\">2</span>\n      <div style=\"flex: 1;\">\n        <div style=\"color: #FF007F; font-weight: 600; font-size: 14px; margin-bottom: 2px;\">Integration for Total Elongation &Delta;L</div>\n        <div style=\"color: #E2E8F0; font-size: 14px; line-height: 1.5;\">W = \\int_0<sup>&Delta;L</sup> (Y A / L) x\\,dx = (Y A / L) [ (x<sup>2</sup> / 2) ]_0<sup>&Delta;L</sup> = (1 / 2) (Y A (&Delta;L)<sup>2</sup> / L)</div>\n      </div>\n    </div>\n  \n    <div style=\"display: flex; gap: 12px; margin-bottom: 12px; align-items: flex-start;\">\n      <span style=\"background: rgba(255, 0, 127, 0.2); color: #FF007F; font-weight: bold; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 12px; border: 1px solid #FF007F;\">3</span>\n      <div style=\"flex: 1;\">\n        <div style=\"color: #FF007F; font-weight: 600; font-size: 14px; margin-bottom: 2px;\">Total Elastic Potential Energy Formula</div>\n        <div style=\"color: #E2E8F0; font-size: 14px; line-height: 1.5;\">Rewriting as W = (1 / 2) ((Y A &Delta;L / L)) &Delta;L = (1 / 2) F &Delta;L: U = (1 / 2) &times; Stretching Force &times; Extension</div>\n      </div>\n    </div>\n  \n    <div style=\"display: flex; gap: 12px; margin-bottom: 12px; align-items: flex-start;\">\n      <span style=\"background: rgba(255, 0, 127, 0.2); color: #FF007F; font-weight: bold; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 12px; border: 1px solid #FF007F;\">4</span>\n      <div style=\"flex: 1;\">\n        <div style=\"color: #FF007F; font-weight: 600; font-size: 14px; margin-bottom: 2px;\">Energy Density (Energy per Unit Volume)</div>\n        <div style=\"color: #E2E8F0; font-size: 14px; line-height: 1.5;\">Volume of wire is V = A L. Dividing total energy by volume: u = (U / A L) = (1 / 2)((F / A))((&Delta;L / L)) = (1 / 2) &times; Stress &times; Strain = (1 / 2) Y (Strain)<sup>2</sup></div>\n      </div>\n    </div>\n  \n  </div>\n\n  <!-- ========================================== -->\n  <!-- PART 2: MECHANICAL PROPERTIES OF FLUIDS   -->\n  <!-- ========================================== -->\n  <div style=\"background: rgba(255, 0, 127, 0.08); border-left: 4px solid #FF007F; padding: 10px 16px; margin: 30px 0 15px 0; border-radius: 0 6px 6px 0;\">\n    <h2 style=\"color: #FF007F; margin: 0; font-size: 20px; font-weight: bold;\">\n      PART 2: Mechanical Properties of Fluids\n    </h2>\n  </div>\n\n  <h3 style=\"color: #FF007F; margin-top: 20px;\">\n    3. Fluid Pressure, Pascal&apos;s Law & Hydraulic Machines\n  </h3>\n  <p>\n    A fluid (liquid or gas) cannot sustain static shearing stress; it yields and flows under the slightest tangential force. Hence, a static fluid exerts forces exclusively perpendicular (normal) to any surface in contact with it. Fluid pressure at a point is P = dF_{\\perp} / dA.\n  </p>\n\n  <p>\n    <b style=\"color: #FF007F;\">(i) Variation of Pressure with Depth (Fluid Column):</b><br/>\n    For a static fluid of uniform density \rho under uniform gravity g, pressure increases linearly with depth h beneath the free surface:\n    P = P_0 + &rho; g h\n    where P_0 is the atmospheric pressure at the open surface (1.013 &times; 10<sup>5</sup> Pa). The excess pressure above atmospheric pressure, P - P_0 = &rho; g h, is known as <b>gauge pressure</b>.\n  </p>\n\n  \n  <div style=\"background: rgba(255, 0, 127, 0.06); border: 1.5px solid #FF007F; border-radius: 10px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 6px;\">\n      <span style=\"background: #FF007F; color: #FFFFFF; font-weight: bold; font-size: 11px; padding: 2px 8px; border-radius: 4px; text-transform: uppercase; letter-spacing: 0.5px;\">DEFINITION</span>\n      <b style=\"color: #FF007F; font-size: 16px;\">Pascal's Law</b>\n    </div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">Pressure applied to an enclosed, incompressible fluid at rest is transmitted undiminished in all directions to every portion of the fluid and to the walls of the containing vessel.</div>\n    \n    <div style=\"display: flex; gap: 16px; margin-top: 10px; padding-top: 8px; border-top: 1px dashed rgba(255, 0, 127, 0.3); font-size: 13.5px; color: #CBD5E1;\">\n      <span><b>SI Unit:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">Pascal (Pa)</code></span>\n      <span><b>Dimensional Formula:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">[M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</code></span>\n    </div>\n  </div>\n\n  <p>\n    <b style=\"color: #FF007F;\">(ii) Applications of Pascal&apos;s Law:</b><br/>\n    &bull; <b>Hydraulic Lift:</b> Two connected cylinders of cross-sectional areas A_1 and A_2 (A_1 &ll; A_2) are fitted with movable pistons. When a small effort force F_1 is applied on the smaller piston, the transmitted pressure is P = F_1 / A_1. This pressure acts on the large piston, generating an upward lifting force:\n    F_2 = P A_2 = F_1((A_2 / A_1))\n    Since A_2 / A_1 &gg; 1, a modest manual force lifts a heavy automobile.\n    <br/>&bull; <b>Hydraulic Brakes:</b> Depressing the brake pedal forces master cylinder fluid through hydraulic lines into slave cylinders at each wheel, driving brake pads against the wheels with amplified, equalized pressure.\n  </p>\n\n  <h3 style=\"color: #FF007F; margin-top: 20px;\">\n    4. Viscosity, Stokes&apos; Law & Terminal Velocity\n  </h3>\n  <p>\n    When a fluid flows over a solid surface, parallel fluid layers slide over one another with a velocity gradient dv/dx. Internal frictional resistance opposing the relative motion between adjacent fluid layers is termed <b>Viscosity</b>. By Newton&apos;s Law of Viscosity:\n    F = -&eta; A (dv / dx)\n  </p>\n\n  \n  <div style=\"background: rgba(255, 0, 127, 0.06); border: 1.5px solid #FF007F; border-radius: 10px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 6px;\">\n      <span style=\"background: #FF007F; color: #FFFFFF; font-weight: bold; font-size: 11px; padding: 2px 8px; border-radius: 4px; text-transform: uppercase; letter-spacing: 0.5px;\">DEFINITION</span>\n      <b style=\"color: #FF007F; font-size: 16px;\">Stokes' Law</b>\n    </div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">The viscous retarding drag force experienced by a smooth spherical body of radius r moving with instantaneous velocity v through an infinite, stationary viscous fluid of viscosity &eta; is given by: F_v = 6&pi; &eta; r v.</div>\n    \n    <div style=\"display: flex; gap: 16px; margin-top: 10px; padding-top: 8px; border-top: 1px dashed rgba(255, 0, 127, 0.3); font-size: 13.5px; color: #CBD5E1;\">\n      <span><b>SI Unit:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">Newton (N)</code></span>\n      <span><b>Dimensional Formula:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">[M<sup>1</sup> L<sup>1</sup> T<sup>-2</sup>]</code></span>\n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.3); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 14px; border-bottom: 1px solid rgba(255, 0, 127, 0.2); padding-bottom: 8px;\">\n      <span style=\"color: #FF007F; font-size: 18px;\">📐</span>\n      <b style=\"color: #FF007F; font-size: 15.5px;\">Derivation of Terminal Velocity of a Falling Sphere</b>\n    </div>\n    \n    <div style=\"display: flex; gap: 12px; margin-bottom: 12px; align-items: flex-start;\">\n      <span style=\"background: rgba(255, 0, 127, 0.2); color: #FF007F; font-weight: bold; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 12px; border: 1px solid #FF007F;\">1</span>\n      <div style=\"flex: 1;\">\n        <div style=\"color: #FF007F; font-weight: 600; font-size: 14px; margin-bottom: 2px;\">Forces Acting on Falling Sphere</div>\n        <div style=\"color: #E2E8F0; font-size: 14px; line-height: 1.5;\">Consider a sphere of radius r and material density &rho; falling through a fluid of density &sigma; and viscosity &eta;.<br/>1. Downward Weight: W = m g = (4 / 3)&pi; r<sup>3</sup> &rho; g<br/>2. Upward Buoyant Force: F_b = (4 / 3)&pi; r<sup>3</sup> &sigma; g<br/>3. Upward Viscous Drag (Stokes): F_v = 6&pi; &eta; r v</div>\n      </div>\n    </div>\n  \n    <div style=\"display: flex; gap: 12px; margin-bottom: 12px; align-items: flex-start;\">\n      <span style=\"background: rgba(255, 0, 127, 0.2); color: #FF007F; font-weight: bold; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 12px; border: 1px solid #FF007F;\">2</span>\n      <div style=\"flex: 1;\">\n        <div style=\"color: #FF007F; font-weight: 600; font-size: 14px; margin-bottom: 2px;\">Dynamic Force Equilibrium at Terminal Speed</div>\n        <div style=\"color: #E2E8F0; font-size: 14px; line-height: 1.5;\">As speed v increases, viscous drag grows until the net downward driving force is completely balanced by the total upward forces: W = F_b + F_v (4 / 3)&pi; r<sup>3</sup> &rho; g = (4 / 3)&pi; r<sup>3</sup> &sigma; g + 6&pi; &eta; r v_t</div>\n      </div>\n    </div>\n  \n    <div style=\"display: flex; gap: 12px; margin-bottom: 12px; align-items: flex-start;\">\n      <span style=\"background: rgba(255, 0, 127, 0.2); color: #FF007F; font-weight: bold; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 12px; border: 1px solid #FF007F;\">3</span>\n      <div style=\"flex: 1;\">\n        <div style=\"color: #FF007F; font-weight: 600; font-size: 14px; margin-bottom: 2px;\">Solving for Terminal Velocity v_t</div>\n        <div style=\"color: #E2E8F0; font-size: 14px; line-height: 1.5;\">6&pi; &eta; r v_t = (4 / 3)&pi; r<sup>3</sup> (&rho; - &sigma;) g v_t = (4&pi; r<sup>3</sup> (&rho; - &sigma;) g / 3 &times; 6&pi; &eta; r) = (2 / 9)(r<sup>2</sup> (&rho; - &sigma;) g / &eta;)</div>\n      </div>\n    </div>\n  \n    <div style=\"display: flex; gap: 12px; margin-bottom: 12px; align-items: flex-start;\">\n      <span style=\"background: rgba(255, 0, 127, 0.2); color: #FF007F; font-weight: bold; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 12px; border: 1px solid #FF007F;\">4</span>\n      <div style=\"flex: 1;\">\n        <div style=\"color: #FF007F; font-weight: 600; font-size: 14px; margin-bottom: 2px;\">Key Physical Insights</div>\n        <div style=\"color: #E2E8F0; font-size: 14px; line-height: 1.5;\">&bull; Terminal speed is proportional to the square of the radius (v_t &prop; r<sup>2</sup>); larger raindrops plunge much faster than mist droplets.<br/>&bull; If &rho; < &sigma; (e.g. air bubbles in water), v_t is negative, causing the bubble to accelerate upwards.</div>\n      </div>\n    </div>\n  \n  </div>\n\n  <h3 style=\"color: #FF007F; margin-top: 20px;\">\n    5. Streamline Flow, Reynolds Number & Bernoulli&apos;s Theorem\n  </h3>\n  <p>\n    <b style=\"color: #FF007F;\">(i) Streamline vs Turbulent Flow:</b><br/>\n    &bull; <b>Streamline (Laminar) Flow:</b> Fluid particles follow identical, steady streamlines such that every particle passing a given point possesses the exact same velocity in magnitude and direction. Streamlines never intersect.\n    <br/>&bull; <b>Turbulent Flow:</b> When flow speed surpasses a threshold (critical velocity v_c), fluid motion becomes chaotic, unsteady, and characterized by vortices and eddies.\n    <br/>The flow regime is governed by the dimensionless <b>Reynolds Number (R_e)</b>:\n    R_e = (&rho; v d / &eta;)\n    If R_e &lt; 2000, flow is steady laminar; if R_e &gt; 3000, flow is turbulent; between 2000 and 3000, flow is unsteady.\n  </p>\n\n  <p>\n    <b style=\"color: #FF007F;\">(ii) Equation of Continuity:</b><br/>\n    For an incompressible, non-viscous fluid in streamline flow through a pipe of varying cross-section, mass flow rate is conserved:\n    A_1 v_1 = A_2 v_2 = constant\n    Narrower cross-sections require proportionately higher fluid speeds (v &prop; 1/A).\n  </p>\n\n  \n  <div style=\"background: rgba(255, 0, 127, 0.06); border: 1.5px solid #FF007F; border-radius: 10px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 6px;\">\n      <span style=\"background: #FF007F; color: #FFFFFF; font-weight: bold; font-size: 11px; padding: 2px 8px; border-radius: 4px; text-transform: uppercase; letter-spacing: 0.5px;\">DEFINITION</span>\n      <b style=\"color: #FF007F; font-size: 16px;\">Bernoulli's Principle</b>\n    </div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">For the streamline flow of an ideal (incompressible, non-viscous, irrotational) fluid, the total mechanical energy per unit volume—comprising static pressure, kinetic energy, and gravitational potential energy—remains constant throughout the flow: P + (1 / 2)&rho; v<sup>2</sup> + &rho; g h = constant.</div>\n    \n    <div style=\"display: flex; gap: 16px; margin-top: 10px; padding-top: 8px; border-top: 1px dashed rgba(255, 0, 127, 0.3); font-size: 13.5px; color: #CBD5E1;\">\n      <span><b>SI Unit:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">Pascal (Pa)</code></span>\n      <span><b>Dimensional Formula:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">[M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</code></span>\n    </div>\n  </div>\n\n  <p>\n    <b style=\"color: #FF007F;\">(iii) Applications of Bernoulli&apos;s Theorem:</b><br/>\n    &bull; <b>Venturimeter:</b> Measures rate of fluid flow through pipes by registering the pressure drop &Delta;P across a constricted throat: Q = A_1 A_2 &radic;{(2(P_1 - P_2) / &rho; (A_1<sup>2</sup> - A_2<sup>2</sup>))}.\n    <br/>&bull; <b>Torricelli&apos;s Law of Efflux:</b> Speed of liquid spurting through an orifice at depth h beneath the free surface of an open tank equals free-fall speed: v = &radic;(2gh).\n    <br/>&bull; <b>Dynamic Aerodynamic Lift:</b> An aircraft wing (aerofoil) is curved on top and flat below. Air streamlines crowd and travel faster above the top surface (v_{top} &gt; v_{bottom}). By Bernoulli&apos;s law, pressure above the wing drops (P_{top} &lt; P_{bottom}), generating an upward dynamic lift force.\n  </p>\n\n  <h3 style=\"color: #FF007F; margin-top: 20px;\">\n    6. Surface Tension, Surface Energy, Excess Pressure & Capillarity\n  </h3>\n  <p>\n    <b style=\"color: #FF007F;\">(i) Molecular Theory of Surface Tension:</b><br/>\n    A molecule deep inside a liquid experiences equal cohesive attractions in all directions, yielding zero net force. In contrast, a molecule at the surface boundary experiences inward cohesive pull from below with negligible attraction from air molecules above. Consequently, surface molecules possess surplus potential energy (<b>Surface Energy</b>). Liquids naturally contract to minimize surface area, causing the free surface to behave like a stretched elastic membrane under tension.\n    <br/><b>Relation between Surface Tension and Surface Energy:</b>\n    W = T &Delta;A\n    Work done in increasing surface area by Delta A equals T Delta A. Hence, Surface Tension equals Surface Energy per unit area (1 N/m = 1 J/m<sup>2</sup>).\n  </p>\n\n  <p>\n    <b style=\"color: #FF007F;\">(ii) Angle of Contact (&theta;):</b><br/>\n    The angle between the solid surface and the tangent drawn to the liquid meniscus at the point of contact, measured inside the liquid.\n    <br/>&bull; &theta; &lt; 90<sup>&deg;</sup> (Acute): Liquid wets solid; concave meniscus (pure water on clean glass, &theta; &approx; 0<sup>&deg;</sup>).\n    <br/>&bull; &theta; &gt; 90<sup>&deg;</sup> (Obtuse): Liquid does not wet solid; convex meniscus (mercury on glass, &theta; &approx; 135<sup>&deg;</sup>).\n  </p>\n\n  <p>\n    <b style=\"color: #FF007F;\">(iii) Excess Pressure across Curved Interfaces:</b><br/>\n    The pressure on the concave side of a curved liquid surface is always greater than on the convex side.\n    <br/>&bull; <b>Inside a Liquid Drop / Air Bubble in Liquid (1 surface):</b> &Delta;P = P_{in} - P_{out} = (2T / R).\n    <br/>&bull; <b>Inside a Soap Bubble in Air (2 liquid-gas interfaces):</b> &Delta;P = P_{in} - P_{out} = (4T / R).\n  </p>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.3); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 14px; border-bottom: 1px solid rgba(255, 0, 127, 0.2); padding-bottom: 8px;\">\n      <span style=\"color: #FF007F; font-size: 18px;\">📐</span>\n      <b style=\"color: #FF007F; font-size: 15.5px;\">Derivation of Capillary Ascent Formula (Jurin's Law)</b>\n    </div>\n    \n    <div style=\"display: flex; gap: 12px; margin-bottom: 12px; align-items: flex-start;\">\n      <span style=\"background: rgba(255, 0, 127, 0.2); color: #FF007F; font-weight: bold; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 12px; border: 1px solid #FF007F;\">1</span>\n      <div style=\"flex: 1;\">\n        <div style=\"color: #FF007F; font-weight: 600; font-size: 14px; margin-bottom: 2px;\">Meniscus Geometry & Pressure Deficit</div>\n        <div style=\"color: #E2E8F0; font-size: 14px; line-height: 1.5;\">When a narrow glass capillary tube of internal radius r is dipped in a wetting liquid (\theta < 90<sup>c</sup>irc), a concave hemispherical meniscus forms with radius of curvature R = (r / \\cos&theta;). The pressure immediately beneath the concave surface is less than atmospheric pressure P_0 by: &Delta;P = (2T / R) = (2T \\cos&theta; / r)</div>\n      </div>\n    </div>\n  \n    <div style=\"display: flex; gap: 12px; margin-bottom: 12px; align-items: flex-start;\">\n      <span style=\"background: rgba(255, 0, 127, 0.2); color: #FF007F; font-weight: bold; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 12px; border: 1px solid #FF007F;\">2</span>\n      <div style=\"flex: 1;\">\n        <div style=\"color: #FF007F; font-weight: 600; font-size: 14px; margin-bottom: 2px;\">Hydrostatic Column Balance</div>\n        <div style=\"color: #E2E8F0; font-size: 14px; line-height: 1.5;\">To equalize pressure with the external flat surface at atmospheric pressure P_0, the liquid rises along the tube to a height h until the hydrostatic pressure of the column balances the pressure deficit: &rho; g h = &Delta;P = (2T \\cos&theta; / r)</div>\n      </div>\n    </div>\n  \n    <div style=\"display: flex; gap: 12px; margin-bottom: 12px; align-items: flex-start;\">\n      <span style=\"background: rgba(255, 0, 127, 0.2); color: #FF007F; font-weight: bold; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 12px; border: 1px solid #FF007F;\">3</span>\n      <div style=\"flex: 1;\">\n        <div style=\"color: #FF007F; font-weight: 600; font-size: 14px; margin-bottom: 2px;\">Ascent Formula & Jurin's Law</div>\n        <div style=\"color: #E2E8F0; font-size: 14px; line-height: 1.5;\">h = (2T \\cos&theta; / r &rho; g) For a given liquid and tube, h r = constant (Jurin&apos;s Law); narrower capillaries produce dramatically higher capillary ascent.</div>\n      </div>\n    </div>\n  \n  </div>\n\n  <!-- ========================================== -->\n  <!-- PART 3: THERMAL PROPERTIES OF MATTER      -->\n  <!-- ========================================== -->\n  <div style=\"background: rgba(255, 0, 127, 0.08); border-left: 4px solid #FF007F; padding: 10px 16px; margin: 30px 0 15px 0; border-radius: 0 6px 6px 0;\">\n    <h2 style=\"color: #FF007F; margin: 0; font-size: 20px; font-weight: bold;\">\n      PART 3: Thermal Properties of Matter\n    </h2>\n  </div>\n\n  <h3 style=\"color: #FF007F; margin-top: 20px;\">\n    7. Thermal Expansion & Anomalous Expansion of Water\n  </h3>\n  <p>\n    Heating increases the average vibrational amplitude of atoms around their lattice equilibrium positions, expanding material bulk dimensions.\n    <br/>&bull; <b>Coefficient of Linear Expansion (&alpha;):</b> &Delta;L = L_0 &alpha; &Delta;T &rArr; &alpha; = (&Delta;L / L_0 &Delta;T) (K<sup>-1</sup>).\n    <br/>&bull; <b>Coefficient of Area (Superficial) Expansion (&beta;):</b> &Delta;A = A_0 &beta; &Delta;T &rArr; &beta; = 2&alpha;.\n    <br/>&bull; <b>Coefficient of Volume (Cubical) Expansion (&gamma;):</b> &Delta;V = V_0 &gamma; &Delta;T &rArr; &gamma; = 3&alpha;.\n    <br/>Relationship for isotropic solids:\n    &alpha; : &beta; : &gamma; = 1 : 2 : 3\n  </p>\n\n  <p>\n    <b style=\"color: #FF007F;\">Anomalous Expansion of Water:</b><br/>\n    Almost all liquids expand uniformly on heating. Water behaves uniquely: when heated from 0<sup>c</sup>irc\text{C} to 4<sup>c</sup>irc\text{C}, water contracts, its volume decreasing to a minimum and its density reaching a peak maximum of 1000\text{ kg/m}<sup>3</sup> at 4<sup>c</sup>irc\text{C} (gamma &lt; 0). Beyond 4<sup>c</sup>irc\text{C}, water expands normally.\n    <br/><b>Ecological Importance:</b> In severe winters, surface water cools to 4<sup>c</sup>irc\text{C}, becomes densest, and sinks to the bottom. Once the entire lake reaches 4<sup>c</sup>irc\text{C}, further surface cooling makes surface water lighter (0<sup>c</sup>irc\text{C} to 3<sup>c</sup>irc\text{C}), which freezes into ice at the surface. Because ice is an exceptional thermal insulator, the underlying deep water stays liquid at 4<sup>c</sup>irc\text{C}, preserving aquatic life through freezing winters.\n  </p>\n\n  <h3 style=\"color: #FF007F; margin-top: 20px;\">\n    8. Specific Heat Capacity, Calorimetry & Latent Heat\n  </h3>\n  <p>\n    <b style=\"color: #FF007F;\">(i) Specific Heat Capacity (s):</b> Heat energy required to raise the temperature of unit mass of a substance by 1<sup>c</sup>irc\text{C} (or 1\text{ K}): Q = m s &Delta;T &rArr; s = (Q / m &Delta;T) (J kg<sup>-1</sup> K<sup>-1</sup>).\n    <br/><b style=\"color: #FF007F;\">(ii) Molar Specific Heat Capacities of Gases:</b>\n    <br/>&bull; Specific heat at constant volume: C_v = ((dQ / dT))_v.\n    <br/>&bull; Specific heat at constant pressure: C_p = ((dQ / dT))_p.\n    <br/><b>Mayer&apos;s Relation:</b> C_p - C_v = R.\n    <br/><b style=\"color: #FF007F;\">(iii) Principle of Calorimetry:</b> In an insulated system:\n    Heat Lost by Hot Bodies = Heat Gained by Cold Bodies\n    <br/><b style=\"color: #FF007F;\">(iv) Latent Heat (L):</b> Heat energy absorbed or released during a phase change at constant temperature: Q = m L.\n    <br/>&bull; <b>Latent Heat of Fusion (L_f):</b> For ice at 0<sup>c</sup>irc\text{C}, L_f &approx; 3.33 &times; 10<sup>5</sup> J/kg = 80 cal/g.\n    <br/>&bull; <b>Latent Heat of Vaporization (L_v):</b> For water at 100<sup>c</sup>irc\text{C}, L_v &approx; 2.26 &times; 10<sup>6</sup> J/kg = 540 cal/g. (Steam at 100<sup>c</sup>irc\text{C} inflicts far more severe burns than boiling water at 100<sup>c</sup>irc\text{C} due to this stored latent enthalpy).\n  </p>\n\n  <h3 style=\"color: #FF007F; margin-top: 20px;\">\n    9. Heat Transfer, Thermal Conductivity & Radiation Laws\n  </h3>\n  <p>\n    Heat transfers via three distinct modes:\n    <br/>1. <b>Conduction:</b> Transfer of heat through adjacent molecular collisions without gross bodily movement of matter. By Fourier&apos;s Law across a slab of area A, thickness d, and temperature difference Delta T:\n    (dQ / dt) = K A (&Delta;T / d)\n    where K is the <b>thermal conductivity</b> of the material.\n    <br/>2. <b>Convection:</b> Transfer of heat through actual macroscopic bulk circulation of fluid packets driven by gravity and density variations (natural convection drives land and sea breezes; forced convection circulates blood pumped by the heart).\n    <br/>3. <b>Radiation:</b> Transfer of thermal energy via electromagnetic waves (infrared), requiring no material medium (solar energy traveling through vacuum).\n  </p>\n\n  <p>\n    <b style=\"color: #FF007F;\">Blackbody Radiation & Spectral Emission:</b><br/>\n    A perfect blackbody absorbs 100% of incident radiation across all wavelengths. When heated, it emits continuous blackbody thermal radiation.\n  </p>\n\n  \n  <div style=\"background: rgba(255, 0, 127, 0.06); border: 1.5px solid #FF007F; border-radius: 10px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 6px;\">\n      <span style=\"background: #FF007F; color: #FFFFFF; font-weight: bold; font-size: 11px; padding: 2px 8px; border-radius: 4px; text-transform: uppercase; letter-spacing: 0.5px;\">DEFINITION</span>\n      <b style=\"color: #FF007F; font-size: 16px;\">Wien's Displacement Law</b>\n    </div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">The wavelength &lambda;<sub>max</sub> corresponding to the peak emission intensity of a blackbody is inversely proportional to its absolute temperature T: \\lambda_{\\max} T = b, where b is Wien's constant (2.898 &times; 10<sup>-3</sup> m K).</div>\n    \n    <div style=\"display: flex; gap: 16px; margin-top: 10px; padding-top: 8px; border-top: 1px dashed rgba(255, 0, 127, 0.3); font-size: 13.5px; color: #CBD5E1;\">\n      <span><b>SI Unit:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">m K</code></span>\n      <span><b>Dimensional Formula:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">[M<sup>0</sup> L<sup>1</sup> T<sup>0</sup> K<sup>1</sup>]</code></span>\n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(255, 0, 127, 0.06); border: 1.5px solid #FF007F; border-radius: 10px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 6px;\">\n      <span style=\"background: #FF007F; color: #FFFFFF; font-weight: bold; font-size: 11px; padding: 2px 8px; border-radius: 4px; text-transform: uppercase; letter-spacing: 0.5px;\">DEFINITION</span>\n      <b style=\"color: #FF007F; font-size: 16px;\">Stefan-Boltzmann Law</b>\n    </div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">The total thermal radiation energy emitted per second per unit surface area of a perfect blackbody is directly proportional to the fourth power of its absolute temperature: E = &sigma; T<sup>4</sup>, where &sigma; is Stefan's constant (5.67 &times; 10<sup>-8</sup> W m<sup>-2</sup> K<sup>-4</sup>).</div>\n    \n    <div style=\"display: flex; gap: 16px; margin-top: 10px; padding-top: 8px; border-top: 1px dashed rgba(255, 0, 127, 0.3); font-size: 13.5px; color: #CBD5E1;\">\n      <span><b>SI Unit:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">W/m<sup>2</sup></code></span>\n      <span><b>Dimensional Formula:</b> <code style=\"color: #FF80BF; background: rgba(0,0,0,0.3); padding: 1px 6px; border-radius: 4px;\">[M<sup>1</sup> L<sup>0</sup> T<sup>-3</sup> K<sup>-4</sup>]</code></span>\n    </div>\n  </div>\n\n  <p>\n    For a real body with surface emissivity e (0 &lt; e &lt; 1) at temperature T inside surroundings at temperature T_0, the net rate of heat loss by radiation is:\n    (dQ / dt) = e &sigma; A (T<sup>4</sup> - T<sub>0</sub><sup>4</sup>)\n  </p>\n\n  <!-- MASTER FORMULA CHEAT SHEET -->\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 2px solid #FF007F; border-radius: 12px; padding: 18px; margin-top: 35px; box-shadow: 0 4px 20px rgba(0,0,0,0.4);\">\n    <h3 style=\"color: #FF007F; margin: 0 0 12px 0; font-size: 18px; font-weight: bold; text-align: center !important;\">\n      📋 Master Revision Formula Cheat Sheet &bull; Unit VII: Properties of Bulk Matter\n    </h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; font-size: 13.5px; color: #E2E8F0;\">\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: 6px; border-left: 3px solid #FF007F;\">\n        <b style=\"color: #FF007F;\">Solids & Elastic Moduli:</b><br/>\n        Y = (FL / A&Delta;L) &bull; B = -V(&Delta;P / &Delta;V) &bull; &eta; = (F / A&theta;)<br/>\n        Poisson: &sigma; = -(&Delta;d/d / &Delta;L/L) &bull; Energy density: u = (1 / 2)&sigma;\\epsilon\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: 6px; border-left: 3px solid #FF007F;\">\n        <b style=\"color: #FF007F;\">Fluid Statics & Pascal&apos;s Law:</b><br/>\n        P = P_0 + &rho; g h &bull; Gauge = &rho; g h<br/>\n        Hydraulic lift: (F_1 / A_1) = (F_2 / A_2)\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: 6px; border-left: 3px solid #FF007F;\">\n        <b style=\"color: #FF007F;\">Viscosity & Stokes&apos; Law:</b><br/>\n        F = -&eta; A(dv / dx) &bull; Drag: F_v = 6&pi;&eta; r v<br/>\n        Terminal velocity: v_t = (2 / 9)(r<sup>2</sup>(&rho; - &sigma;)g / &eta;)\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: 6px; border-left: 3px solid #FF007F;\">\n        <b style=\"color: #FF007F;\">Fluid Dynamics & Flow:</b><br/>\n        Continuity: A_1 v_1 = A_2 v_2 &bull; Reynolds: R_e = (&rho; v d / &eta;)<br/>\n        Bernoulli: P + (1 / 2)&rho; v<sup>2</sup> + &rho; g h = constant\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: 6px; border-left: 3px solid #FF007F;\">\n        <b style=\"color: #FF007F;\">Surface Tension & Capillarity:</b><br/>\n        Energy: W = T&Delta;A &bull; Drop: &Delta;P = (2T / R) &bull; Bubble: &Delta;P = (4T / R)<br/>\n        Ascent: h = (2T\\cos&theta; / r&rho; g) (Jurin: hr = const)\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: 6px; border-left: 3px solid #FF007F;\">\n        <b style=\"color: #FF007F;\">Thermal Expansion & Calorimetry:</b><br/>\n        &alpha; : &beta; : &gamma; = 1 : 2 : 3 &bull; Q = m s&Delta;T<br/>\n        Q = m L &bull; Mayer: C_p - C_v = R\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: 6px; border-left: 3px solid #FF007F;\">\n        <b style=\"color: #FF007F;\">Heat Transfer & Conduction:</b><br/>\n        Fourier: (dQ / dt) = K A(&Delta;T / d) &bull; Resistance: R_{th} = (d / KA)\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px; border-radius: 6px; border-left: 3px solid #FF007F;\">\n        <b style=\"color: #FF007F;\">Thermal Radiation Laws:</b><br/>\n        Wien: \\lambda_{\\max} T = b (2.898 &times; 10<sup>-3</sup> m K)<br/>\n        Stefan: E = &sigma; T<sup>4</sup> &bull; Net: (dQ / dt) = e&sigma; A(T<sup>4</sup> - T<sub>0</sub><sup>4</sup>)$\n      </div>\n    </div>\n  </div>\n\n</div>";

export const c11Phy7HtmlSolutions = "\n<div style=\"font-family: 'Outfit', sans-serif; color: #E2E8F0; line-height: 1.6; max-width: 900px; margin: 0 auto; padding: 10px;\">\n  <div style=\"text-align: center; margin-bottom: 25px; padding: 15px; background: rgba(255, 0, 127, 0.08); border-radius: 8px; border: 1px solid rgba(255, 0, 127, 0.2);\">\n    <h1 style=\"color: #FF007F; font-size: 24px; margin: 0 0 8px 0; font-weight: 700;\">Chapter 7: Properties of Bulk Matter — Complete 100 Questions & Answers</h1>\n    <p style=\"color: #94A3B8; font-size: 14px; margin: 0;\">Comprehensive Reference Solutions: Section A (Q1–Q40 VSA 1 Mark), Section B (Q41–Q80 SA 2 & 3 Marks), Section C (Q81–Q100 LA 5 Marks)</p>\n  </div>\n\n  \n  <!-- SECTION A: VERY SHORT ANSWER (VSA) QUESTIONS (1 MARK EACH) -->\n  <div style=\"background: rgba(255, 0, 127, 0.08); border-left: 4px solid #FF007F; padding: 12px 16px; margin: 25px 0 15px 0; border-radius: 0 8px 8px 0;\">\n    <h3 style=\"color: #FF007F; margin: 0; font-size: 18px; font-weight: bold;\">\n      SECTION A: Very Short Answer (VSA) Questions (1 Mark Each) &bull; Q1 to Q40\n    </h3>\n    <p style=\"color: #CBD5E1; margin: 5px 0 0 0; font-size: 13px;\">\n      Fundamental definitions, elasticity coefficients, fluid laws, surface tension, and thermal quantities across Solids, Fluids, and Thermal physics.\n    </p>\n  </div>\n\n  <!-- Q1 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q1: Define the elasticity of a solid body.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> <b>Elasticity</b> is the property of a material body by virtue of which it tends to restore its original shape and size after the removal of external deforming forces.\n    </p>\n  </div>\n\n  <!-- Q2 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q2: State Hooke&apos;s Law of elasticity.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> Within the proportional elastic limit of a material, the internal restoring <b>stress</b> developed is directly proportional to the <b>strain</b> produced:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      Stress &prop; Strain &rArr; (Stress / Strain) = E \\quad (Modulus of Elasticity)\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q3: Define stress. State its SI unit and dimensional formula.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> <b>Stress</b> is the internal restoring force per unit cross-sectional area developed inside a deformed body: &sigma; = F_{res} / A.\n      <br/>&bull; <b>SI Unit:</b> Newton per square-metre (<b>N/m<sup>2</sup></b> or <b>Pascal, Pa</b>)\n      <br/>&bull; <b>Dimensional Formula:</b> <b>[M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</b>\n    </p>\n  </div>\n\n  <!-- Q4 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q4: Define strain. Why is strain a dimensionless physical quantity?</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> <b>Strain</b> is the fractional change in dimension produced in a body: Strain = &Delta;L / L (or &Delta;V / V). Because it represents the ratio of two identical physical dimensions, it has no units and is purely dimensionless ([M<sup>0</sup> L<sup>0</sup> T<sup>0</sup>]).\n    </p>\n  </div>\n\n  <!-- Q5 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q5: Between steel and rubber, which is more elastic in physics? Justify.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> <b>Steel is more elastic than rubber.</b> For a given applied stretching stress, steel produces a far smaller strain than rubber. Consequently, Young&apos;s modulus of steel is vastly greater (Y_{steel} &gg; Y_{rubber}), which means steel offers far greater resistance to deformation.\n    </p>\n  </div>\n\n  <!-- Q6 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q6: State the SI unit and dimensional formula of Young&apos;s Modulus.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> \n      <br/>&bull; <b>SI Unit:</b> Pascal (<b>Pa</b>) or <b>N/m<sup>2</sup></b>\n      <br/>&bull; <b>Dimensional Formula:</b> <b>[M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</b> (identical to stress and pressure)\n    </p>\n  </div>\n\n  <!-- Q7 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q7: Define Bulk Modulus of elasticity.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> <b>Bulk Modulus</b> (B) is the ratio of hydraulic (volume) stress to the corresponding volumetric strain within the elastic limit:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      B = -(&Delta;P / &Delta;V / V) = -V (&Delta;P / &Delta;V)\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q8: Define compressibility of a material.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> <b>Compressibility</b> (k) is defined as the reciprocal of the Bulk Modulus: k = 1/B.\n      <br/>&bull; <b>SI Unit:</b> <b>m<sup>2</sup>/N</b> or <b>Pa<sup>-1</sup></b> &bull; Dimensions: <b>[M<sup>-1</sup> L<sup>1</sup> T<sup>2</sup>]</b>.\n    </p>\n  </div>\n\n  <!-- Q9 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q9: Define Shear Modulus of Rigidity (&eta;).</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> <b>Shear Modulus</b> is the ratio of tangential (shearing) stress to shearing strain: &eta; = (F / A / &theta;) (N/m<sup>2</sup>). Liquids and gases have &eta; = 0 because they cannot support static shear.\n    </p>\n  </div>\n\n  <!-- Q10 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q10: Define Poisson&apos;s ratio (&sigma;) and state its formula.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> Within the elastic limit, <b>Poisson&apos;s ratio</b> is the ratio of lateral strain to longitudinal strain:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      &sigma; = (Lateral Strain / Longitudinal Strain) = -(&Delta;d / d / &Delta;L / L)\n    </div>\n  </div>\n\n  <!-- Q11 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q11: State the theoretical and practical limits of Poisson&apos;s ratio.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> \n      <br/>&bull; <b>Theoretical Limits:</b> -1 &le; &sigma; &le; +0.5\n      <br/>&bull; <b>Practical Limits:</b> 0 &le; &sigma; &le; 0.5 (metals typically range from 0.25 to 0.35; rubber is &approx; 0.5).\n    </p>\n  </div>\n\n  <!-- Q12 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q12: Write the expression for the elastic potential energy density in a stretched wire.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> Energy density (energy per unit volume) is:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      u = (1 / 2) &times; Stress &times; Strain = (1 / 2) Y (Strain)<sup>2</sup> = (Stress<sup>2</sup> / 2Y)\n    </div>\n  </div>\n\n  <!-- Q13 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q13: What are elastomers? Give an everyday biological example.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> <b>Elastomers</b> are materials that can be subjected to very large elastic strains (hundreds of percent) without undergoing plastic deformation, exhibiting non-linear stress-strain response. <i>Example:</i> <b>Vulcanized rubber</b> and the <b>elastic tissue of the human aorta</b>.\n    </p>\n  </div>\n\n  <!-- Q14 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q14: Define fluid pressure. State its SI unit and dimensional formula.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> Fluid pressure is the normal thrust force exerted per unit surface area by a fluid at rest: P = F_{\\perp} / A.\n      <br/>&bull; <b>SI Unit:</b> Pascal (<b>Pa</b>) or <b>N/m<sup>2</sup></b>\n      <br/>&bull; <b>Dimensional Formula:</b> <b>[M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</b>\n    </p>\n  </div>\n\n  <!-- Q15 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q15: State Pascal&apos;s Law for transmission of fluid pressure.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> Pressure applied to an enclosed, incompressible fluid at rest is transmitted <b>undiminished in all directions</b> to every point of the fluid and to the walls of the containing vessel.\n    </p>\n  </div>\n\n  <!-- Q16 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q16: Name two common engineering machines based on Pascal&apos;s Law.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> \n      <br/>1. <b>Hydraulic Lift</b> (used in automobile repair workshops).\n      <br/>2. <b>Hydraulic Brakes</b> (used in motor vehicles).\n    </p>\n  </div>\n\n  <!-- Q17 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q17: What is the hydrostatic paradox?</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The liquid pressure at the base of a container depends exclusively on the liquid column height h and density \rho (P = \rho g h), and is completely independent of the shape, volume, or cross-sectional area of the containing vessel.\n    </p>\n  </div>\n\n  <!-- Q18 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q18: Define the coefficient of viscosity (&eta;) of a fluid.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The <b>coefficient of viscosity</b> is the tangential viscous drag force acting per unit surface area between two parallel fluid layers moving with a unit velocity gradient (dv/dx = 1 s<sup>-1</sup>):\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      &eta; = (F / A(dv/dx))\n    </div>\n  </div>\n\n  <!-- Q19 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q19: State the SI unit and dimensional formula of the coefficient of viscosity.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> \n      <br/>&bull; <b>SI Unit:</b> Pascal-second (<b>Pa s</b> or <b>kg m<sup>-1</sup> s<sup>-1</sup></b> or <b>Poiseuille, Pl</b>; 1 Pl = 10 Poise)\n      <br/>&bull; <b>Dimensional Formula:</b> <b>[M<sup>1</sup> L<sup>-1</sup> T<sup>-1</sup>]</b>\n    </p>\n  </div>\n\n  <!-- Q20 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q20: State Stokes&apos; Law for the viscous drag on a spherical particle.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The backward retarding viscous force F_v experienced by a spherical body of radius r moving with instantaneous velocity v in a fluid of viscosity eta is:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      F_v = 6&pi; &eta; r v\n    </div>\n  </div>\n\n  <!-- Q21 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q21: Define terminal velocity.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The maximum constant velocity attained by a body falling through a viscous fluid when the net downward gravitational force is completely balanced by the sum of upward buoyant and viscous drag forces.\n    </p>\n  </div>\n\n  <!-- Q22 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q22: How does the terminal velocity of a falling spherical raindrop depend upon its radius r?</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> Terminal velocity is directly proportional to the <b>square of the radius</b>:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      v_t &prop; r<sup>2</sup> \\quad (v_t = (2 / 9)(r<sup>2</sup>(&rho; - &sigma;)g / &eta;))\n    </div>\n  </div>\n\n  <!-- Q23 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q23: Distinguish in one sentence between streamline flow and turbulent flow.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> In <b>streamline flow</b>, each fluid particle follows a smooth, orderly trajectory identical to preceding particles, whereas in <b>turbulent flow</b>, motion is disorderly, chaotic, and accompanied by churning eddies and vortices.\n    </p>\n  </div>\n\n  <!-- Q24 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q24: Define critical velocity of fluid flow.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The limiting threshold speed below which the flow of a fluid remains steady and streamline, and above which it becomes disordered and turbulent: v_c = (R_e &eta; / &rho; d).\n    </p>\n  </div>\n\n  <!-- Q25 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q25: State the physical significance of Reynolds number (R<sub>e</sub>).</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> Reynolds number (R_e = &rho; v d / &eta;) represents the ratio of inertial forces to viscous forces in a flowing fluid; it predicts whether flow is laminar (R_e &lt; 2000) or turbulent (R_e &gt; 3000).\n    </p>\n  </div>\n\n  <!-- Q26 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q26: State the Equation of Continuity for steady fluid flow.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> For an incompressible, non-viscous fluid in streamline flow, the mass flow rate remains constant across every cross-section:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      A_1 v_1 = A_2 v_2 = constant\n    </div>\n  </div>\n\n  <!-- Q27 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q27: State Bernoulli&apos;s Principle in mathematical form.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> For an ideal fluid in streamline motion, total mechanical energy per unit volume is conserved:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      P + (1 / 2)&rho; v<sup>2</sup> + &rho; g h = constant\n    </div>\n  </div>\n\n  <!-- Q28 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q28: Which fundamental conservation principle forms the basis of Bernoulli&apos;s theorem?</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The <b>Law of Conservation of Energy</b> applied to flowing fluids (Work-Energy Theorem per unit volume).\n    </p>\n  </div>\n\n  <!-- Q29 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q29: Define Surface Tension of a liquid. State its SI unit.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The tangential force acting per unit length along an imaginary line drawn on the free surface of a liquid: T = F / L.\n      <br/>&bull; <b>SI Unit:</b> <b>N/m</b> (or <b>J/m<sup>2</sup></b>) &bull; Dimensions: <b>[M<sup>1</sup> L<sup>0</sup> T<sup>-2</sup>]</b>.\n    </p>\n  </div>\n\n  <!-- Q30 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q30: State the relationship between surface tension and surface energy.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The work done in increasing the free surface area by Delta A equals surface tension times area change:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      W = T &Delta;A &rArr; T = (W / &Delta;A) = Surface Energy per unit area\n    </div>\n  </div>\n\n  <!-- Q31 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q31: Why do freely falling liquid drops and soap bubbles assume spherical shapes?</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> Because of surface tension, liquids naturally contract to minimize their surface area and surface energy. For a given volume, a <b>sphere</b> possesses the absolute minimum surface area.\n    </p>\n  </div>\n\n  <!-- Q32 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q32: Write the formula for excess pressure inside a spherical liquid drop of radius R.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> A drop has only <b>one</b> liquid-air interface:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      &Delta;P = P_{in} - P_{out} = (2T / R)\n    </div>\n  </div>\n\n  <!-- Q33 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q33: Write the formula for excess pressure inside a soap bubble of radius R in air.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> A hollow soap bubble has <b>two</b> liquid-air interfaces (inner and outer surfaces):\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      &Delta;P = P_{in} - P_{out} = (4T / R)\n    </div>\n  </div>\n\n  <!-- Q34 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q34: What is the angle of contact? State its value for pure water in contact with clean glass.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The angle between the solid surface and the tangent drawn to the liquid meniscus at the contact line, measured inside the liquid. For pure water and clean glass, &theta; &approx; 0<sup>&deg;</sup>.\n    </p>\n  </div>\n\n  <!-- Q35 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q35: State Jurin&apos;s Law of capillary ascent.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The height h to which a liquid rises in a capillary tube is inversely proportional to the tube radius r:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      h &prop; (1 / r) &rArr; h r = constant = (2T\\cos&theta; / &rho; g)\n    </div>\n  </div>\n\n  <!-- Q36 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q36: State the relation between linear (&alpha;), superficial (&beta;), and cubical (&gamma;) thermal expansion coefficients for an isotropic solid.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> \n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      &alpha; : &beta; : &gamma; = 1 : 2 : 3 &rArr; &beta; = 2&alpha;, \\quad &gamma; = 3&alpha;\n    </div>\n  </div>\n\n  <!-- Q37 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q37: What is the anomalous expansion of water? At what temperature is its density maximum?</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> When water is heated from 0<sup>c</sup>irc\text{C} to 4<sup>c</sup>irc\text{C}, it anomalous contracts rather than expands, reaching its <b>maximum density (1000 kg/m<sup>3</sup>) at 4&deg;C</b>.\n    </p>\n  </div>\n\n  <!-- Q38 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q38: State Mayer&apos;s Relation connecting molar heat capacities of an ideal gas.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The difference between molar specific heat at constant pressure (C_p) and constant volume (C_v) equals the universal gas constant R:\n    </p>\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 3px solid #FF007F; padding: 8px 12px; border-radius: 4px; margin-top: 8px;\">\n      C_p - C_v = R\n    </div>\n  </div>\n\n  <!-- Q39 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q39: Define latent heat of vaporization. State its numerical value for water.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> The quantity of heat energy required to convert unit mass of liquid into vapour at its boiling point without any change in temperature:\n      $L_v &approx; 2.26 &times; 10<sup>6</sup> J/kg = 540 cal/g\n    </p>\n  </div>\n\n  <!-- Q40 -->\n  <div style=\"background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 0, 127, 0.25); border-radius: 8px; padding: 14px; margin-bottom: 14px;\">\n    <h3 style=\"color: #FF007F; margin-top: 0; margin-bottom: 8px; font-size: 15px;\">Q40: State Wien&apos;s Displacement Law and Stefan-Boltzmann Law in mathematical form.</h3>\n    <p style=\"margin: 0; color: #E2E8F0;\">\n      <b style=\"color: #FF007F;\">Answer:</b> \n      <br/>&bull; <b>Wien&apos;s Displacement Law:</b> \\lambda_{\\max} T = b = 2.898 &times; 10<sup>-3</sup> m K\n      <br/>&bull; <b>Stefan-Boltzmann Law:</b> E = &sigma; T<sup>4</sup> &bull; (sigma = 5.67 &times; 10<sup>-8</sup> W m<sup>-2</sup> K<sup>-4</sup>)\n    </p>\n  </div>\n\n  \n<!-- SECTION B: SHORT ANSWER (SA) QUESTIONS (2 & 3 MARKS) (Q41 TO Q80) -->\n<div style=\"margin-top: 35px; margin-bottom: 20px; padding-bottom: 10px; border-bottom: 2px solid #FF007F;\">\n  <h2 style=\"color: #FF007F; font-size: 20px; margin: 0;\">SECTION B: SHORT ANSWER (SA) QUESTIONS (2 & 3 MARKS)</h2>\n  <p style=\"color: #94A3B8; font-size: 13px; margin: 4px 0 0 0;\">Comprehensive board numericals, conceptual reasoning, 2-mark derivations, and analytical comparisons across Solids, Fluids, and Thermal Physics.</p>\n</div>\n\n<!-- SOLIDS SA QUESTIONS (Q41 to Q52) -->\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q41: Why is Steel More Elastic Than Rubber? Provide Mathematical Proof</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> By considering two wires of equal length and cross-sectional area—one made of steel and the other of rubber—subjected to the same stretching force, prove mathematically why steel is regarded as more elastic than rubber in physics.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Let two wires of steel and rubber have identical original length L and identical cross-sectional area A. Let equal stretching force F be applied to each wire.<br/>\n    The elongation produced in the steel wire is &Delta;L_s and in the rubber wire is &Delta;L_r. Young's modulus for each material is:\n    Y_s = (F &middot; L / A &middot; &Delta;L_s) \\quad and \\quad Y_r = (F &middot; L / A &middot; &Delta;L_r)\n    Dividing the two equations gives:\n    (Y_s / Y_r) = (&Delta;L_r / &Delta;L_s)\n    Experimentally, for the same deforming force, rubber stretches vastly more than steel, i.e., &Delta;L_r &gg; &Delta;L_s. Therefore:\n    (Y_s / Y_r) > 1 &rArr; Y_s > Y_r\n    In physics, elasticity is measured by the magnitude of restoring force developed per unit strain (measured by modulus of elasticity), not by how easily an object stretches. Since steel offers greater restoring stress and resists deformation much more strongly, steel is strictly more elastic than rubber.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q42: Calculation of Elongation of a Suspended Steel Wire Under Load</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A steel wire of length 2.0 m and radius 1.0 mm is clamped firmly at one end and carries a mass of 4.0 kg suspended at its free end. Calculate the elongation produced in the wire. Take g = 9.8 m/s<sup>2</sup> and Y_{steel} = 2.0 &times; 10<sup>11</sup> N/m<sup>2</sup>.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Given:\n    Original length L = 2.0 m, radius r = 1.0 mm = 1.0 &times; 10<sup>-3</sup> m.<br/>\n    Cross-sectional area A = &pi; r<sup>2</sup> = 3.1416 &times; (10<sup>-3</sup>)<sup>2</sup> = 3.1416 &times; 10<sup>-6</sup> m<sup>2</sup>.<br/>\n    Stretching force F = mg = 4.0 &times; 9.8 = 39.2 N.<br/>\n    Young's modulus Y = 2.0 &times; 10<sup>11</sup> N/m<sup>2</sup>.<br/>\n    Using the formula for Young's modulus:\n    Y = (F &middot; L / A &middot; &Delta;L) &rArr; &Delta;L = (F &middot; L / A &middot; Y)\n    Substituting the values:\n    &Delta;L = {39.2 &times; 2.0}{(3.1416 &times; 10<sup>-6</sup>) &times; (2.0 &times; 10<sup>11</sup>)} = {78.4}{6.2832 &times; 10<sup>5</sup>} &approx; 1.25 &times; 10<sup>-4</sup> m = 0.125 mm\n    Hence, the elongation produced in the steel wire is <strong>0.125 mm</strong> (or 1.25 &times; 10<sup>-4</sup> m).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q43: Calculation of Work Done in Stretching a Wire and Energy Density</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A copper wire of length 3 m and cross-sectional area 1.5 mm<sup>2</sup> is stretched by a force of 150 N. If Young's modulus of copper is 1.2 &times; 10<sup>11</sup> N/m<sup>2</sup>, calculate: (i) the elongation of the wire, (ii) the work done in stretching the wire, and (iii) the elastic potential energy stored per unit volume.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Given: L = 3 m, A = 1.5 mm<sup>2</sup> = 1.5 &times; 10<sup>-6</sup> m<sup>2</sup>, F = 150 N, Y = 1.2 &times; 10<sup>11</sup> N/m<sup>2</sup>.<br/>\n    <strong>(i) Elongation:</strong>\n    &Delta;L = (F &middot; L / A &middot; Y) = {150 &times; 3}{(1.5 &times; 10<sup>-6</sup>) &times; (1.2 &times; 10<sup>11</sup>)} = {450}{1.8 &times; 10<sup>5</sup>} = 2.5 &times; 10<sup>-3</sup> m = 2.5 mm\n    <strong>(ii) Work Done (Elastic Potential Energy):</strong>\n    W = (1 / 2) F &middot; &Delta;L = (1 / 2) &times; 150 &times; (2.5 &times; 10<sup>-3</sup>) = 0.1875 J\n    <strong>(iii) Energy Density (energy per unit volume):</strong>\n    u = (W / Volume) = (W / A &middot; L) = {0.1875}{(1.5 &times; 10<sup>-6</sup>) &times; 3} = {0.1875}{4.5 &times; 10<sup>-6</sup>} &approx; 41,667 J/m<sup>3</sup> = 4.17 &times; 10<sup>4</sup> J/m<sup>3</sup>\n    Alternatively: u = (1 / 2) &times; stress &times; strain = (1 / 2) &times; ({150}{1.5 &times; 10<sup>-6</sup>}) &times; ({2.5 &times; 10<sup>-3</sup>}{3}) = 4.17 &times; 10<sup>4</sup> J/m<sup>3</sup>.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q44: Bulk Modulus and Fractional Compression of Water at Ocean Depths</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> The bulk modulus of water is 2.1 &times; 10<sup>9</sup> N/m<sup>2</sup>. Compute the fractional compression (&Delta;V / V) of a volume of water at a depth in the ocean where the hydrostatic pressure is 2.0 &times; 10<sup>7</sup> N/m<sup>2</sup> (roughly 200 atmospheres). By what percentage does the volume decrease?</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Given: Bulk modulus B = 2.1 &times; 10<sup>9</sup> N/m<sup>2</sup>, increase in pressure &Delta;P = 2.0 &times; 10<sup>7</sup> N/m<sup>2</sup>.<br/>\n    By definition of Bulk modulus:\n    B = -(&Delta;P / &Delta;V / V) &rArr; \\left|(&Delta;V / V)\\right| = (&Delta;P / B)\n    Substituting the given values:\n    \\left|(&Delta;V / V)\\right| = {2.0 &times; 10<sup>7</sup>}{2.1 &times; 10<sup>9</sup>} = (2.0 / 210) &approx; 9.52 &times; 10<sup>-3</sup> = 0.00952\n    Percentage decrease in volume:\n    \\%  decrease = \\left|(&Delta;V / V)\\right| &times; 100\\% = 0.00952 &times; 100\\% &approx; 0.952\\%\n    This remarkably small volume decrease (less than 1%) demonstrates why liquids are treated as practically incompressible in ordinary fluid mechanics.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q45: Distinguish Between Ductile, Brittle, and Elastomeric Materials</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Differentiate clearly between ductile materials, brittle materials, and elastomers on the basis of their stress-strain behavior, plastic deformation region, and give two engineering or biological examples of each.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">1. Ductile Materials:</b> These materials possess a large plastic deformation range between the elastic limit and the fracture point. They can be drawn into thin wires or sheets without fracturing (e.g., mild steel, copper, aluminium, gold).<br/>\n    <b style=\"color: #FF007F;\">2. Brittle Materials:</b> These materials fracture almost immediately after exceeding the elastic limit with virtually zero plastic deformation range. The yield point and breaking point are very close together (e.g., cast iron, glass, ceramic, chalk).<br/>\n    <b style=\"color: #FF007F;\">3. Elastomers:</b> These materials can undergo enormous elastic strains (several hundred percent) reversibly, but do not obey Hooke's law over most of the range, showing non-linear stress-strain curves with pronounced elastic hysteresis (e.g., vulcanized rubber, tissue of aorta).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q46: Poisson's Ratio: Definition, Theoretical vs Practical Limits</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Define Poisson's ratio (&sigma;). Explain why a stretching force causes lateral contraction. State the theoretical limits of Poisson's ratio and its practical range for ordinary engineering materials.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    When a deforming longitudinal tensile force is applied to a cylindrical wire of original length L and diameter D, its length increases by &Delta;L while its diameter simultaneously contracts by &Delta;D.<br/>\n    <b style=\"color: #FF007F;\">Definition:</b> Within the elastic limit, the ratio of lateral strain to longitudinal strain is constant for a given material and is known as <strong>Poisson's ratio</strong> (&sigma;):\n    &sigma; = (Lateral Strain / Longitudinal Strain) = -(&Delta;D / D / &Delta;L / L)\n    The negative sign signifies that when length increases (&Delta;L > 0), the lateral dimension decreases (&Delta;D < 0).<br/>\n    <b style=\"color: #FF007F;\">Theoretical Limits:</b> From classical elasticity theory of isotropic solids, -1.0 &le; &sigma; &le; +0.5.<br/>\n    <b style=\"color: #FF007F;\">Practical Limits:</b> For all standard natural solid materials, lateral dimensions decrease during tensile elongation, so &sigma; is positive. The practical range for engineering materials (steel, brass, copper, aluminium) is <strong>0.20 &le; &sigma; &le; 0.40</strong>. For ideal incompressible materials (like rubber), &sigma; &approx; 0.50, while for cork &sigma; &approx; 0.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q47: Why are Heavy Structural Girders Shaped as I-Beams (I-Section)?</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> In the construction of bridges and multi-storey buildings, structural steel girders are designed with an I-shaped cross-section rather than a solid rectangular cross-section. Explain the physical and mathematical reasons behind this design.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    When a horizontal girder of length L, breadth b, and depth d supported at both ends carries a central load W, the vertical sag or depression \\delta at its center is given by:\n    \\delta = {W &middot; L<sup>3</sup>}{4 Y b d<sup>3</sup>}\n    From this formula:<br/>\n    1. Depression \\delta is inversely proportional to the cube of depth (d<sup>3</sup>), whereas it is inversely proportional to breadth (b) only to the first power. Thus, increasing depth is vastly more effective in reducing depression and preventing bending than increasing width.<br/>\n    2. However, a deep, narrow rectangular bar has a tendency to buckle sideways under heavy vertical loads.<br/>\n    3. During bending, maximum compressive stress occurs at the top surface, maximum tensile stress occurs at the bottom surface, and stress at the central neutral layer is practically zero.<br/>\n    Therefore, in an <strong>I-section girder</strong>, large flanges are provided at the top and bottom (where stresses are highest) connected by a thinner central vertical web. This maximizes resistance to bending, provides lateral stability against buckling, and significantly reduces the weight and cost of the girder.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q48: Breaking Stress vs Breaking Force for Thick vs Thin Wires</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A heavy load is supported by a wire of radius r. If the radius of the wire is doubled, what will be the effect on: (i) the breaking stress of the material, and (ii) the maximum load (breaking load) the wire can support without breaking?</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <strong>(i) Breaking Stress:</strong> Breaking stress is an intensive property of the material dependent solely on interatomic bonding and metallurgical structure. It is strictly independent of the dimensions (length or radius) of the wire. Therefore, when the radius of the wire is doubled, the breaking stress <strong>remains unchanged</strong>.<br/>\n    <strong>(ii) Maximum Breaking Load:</strong> The breaking load F_{break} is given by:\n    F_{break} = Breaking Stress &times; A = Breaking Stress &times; (&pi; r<sup>2</sup>)\n    Since area A &prop; r<sup>2</sup>, doubling the radius (r' = 2r) increases the cross-sectional area by a factor of 2<sup>2</sup> = 4.<br/>\n    Consequently, the maximum breaking load becomes:\n    F'_{break} = 4 &middot; F_{break}\n    The maximum load the wire can sustain without breaking increases by <strong>4 times</strong> (four-fold).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q49: Calculation of Lateral Strain and Change in Diameter Using Poisson's Ratio</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A brass rod of diameter 10 mm and length 1.0 m is subjected to a tensile force that causes a longitudinal elongation of 0.5 mm. If Poisson's ratio for brass is 0.35, determine: (i) the longitudinal strain, (ii) the lateral strain, and (iii) the change in the diameter of the rod.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Given: D = 10 mm = 1.0 &times; 10<sup>-2</sup> m, L = 1.0 m, &Delta;L = 0.5 mm = 5.0 &times; 10<sup>-4</sup> m, &sigma; = 0.35.<br/>\n    <strong>(i) Longitudinal Strain:</strong>\n    \\epsilon_{long} = (&Delta;L / L) = {5.0 &times; 10<sup>-4</sup>}{1.0} = 5.0 &times; 10<sup>-4</sup>\n    <strong>(ii) Lateral Strain:</strong>\n    From &sigma; = {\\epsilon_{lat}}{\\epsilon_{long}}, we have:\n    \\epsilon_{lat} = &sigma; &times; \\epsilon_{long} = 0.35 &times; (5.0 &times; 10<sup>-4</sup>) = 1.75 &times; 10<sup>-4</sup>\n    <strong>(iii) Change in Diameter:</strong>\n    \\epsilon_{lat} = (|&Delta;D| / D) &rArr; |&Delta;D| = \\epsilon_{lat} &times; D = (1.75 &times; 10<sup>-4</sup>) &times; 10 mm = 1.75 &times; 10<sup>-3</sup> mm = 1.75 &mu;m\n    Since elongation causes lateral contraction, the diameter decreases by <strong>1.75 &times; 10<sup>-3</sup> mm</strong>.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q50: Shear Modulus of Rigidity: Physical Intuition and Displaced Faces</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A metallic cube of side 10 cm has its bottom face rigidly clamped to a tabletop. A tangential horizontal force of 5.0 &times; 10<sup>4</sup> N is applied to its top face. If the shear modulus of the metal is 2.5 &times; 10<sup>10</sup> N/m<sup>2</sup>, calculate: (i) the shearing stress, (ii) the shear strain (in radians), and (iii) the lateral displacement of the top edge relative to the bottom face.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Given: Side of cube L = 10 cm = 0.10 m. Area of top face A = L<sup>2</sup> = (0.10)<sup>2</sup> = 0.01 m<sup>2</sup> = 10<sup>-2</sup> m<sup>2</sup>.<br/>\n    Tangential force F = 5.0 &times; 10<sup>4</sup> N, shear modulus G = 2.5 &times; 10<sup>10</sup> N/m<sup>2</sup>.<br/>\n    <strong>(i) Shearing Stress:</strong>\n    \\sigma_s = (F / A) = {5.0 &times; 10<sup>4</sup>}{10<sup>-2</sup>} = 5.0 &times; 10<sup>6</sup> N/m<sup>2</sup>\n    <strong>(ii) Shearing Strain (&theta;):</strong>\n    G = (\\sigma_s / &theta;) &rArr; &theta; = (\\sigma_s / G) = {5.0 &times; 10<sup>6</sup>}{2.5 &times; 10<sup>10</sup>} = 2.0 &times; 10<sup>-4</sup> radians\n    <strong>(iii) Lateral Displacement (&Delta;x):</strong>\n    &theta; &approx; (&Delta;x / L) &rArr; &Delta;x = &theta; &middot; L = (2.0 &times; 10<sup>-4</sup>) &times; 0.10 = 2.0 &times; 10<sup>-5</sup> m = 0.02 mm\n    The top edge is laterally displaced by <strong>0.02 mm</strong> (20 &mu;m).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q51: Explain Elastic After-Effect and Elastic Fatigue with Real-World Examples</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Clearly explain: (i) Elastic after-effect, and (ii) Elastic fatigue. Why are railway bridges declared unsafe after prolonged service of 50 to 60 years?</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">(i) Elastic After-Effect:</b> The temporary time delay in recovering original dimensions completely after the removal of deforming forces is known as the elastic after-effect. For substances like phosphor-bronze and quartz, this delay is virtually zero, making them ideal suspension fibers in moving-coil galvanometers.<br/>\n    <b style=\"color: #FF007F;\">(ii) Elastic Fatigue:</b> The progressive loss of elastic strength and resilience of a material subjected to repeated, alternating cyclic stresses over a prolonged duration is called elastic fatigue. Under continuous cycles of loading and unloading, micro-cracks develop in the crystal lattice.<br/>\n    <b style=\"color: #FF007F;\">Bridge Safety:</b> A railway bridge undergoes continuous cyclic loading every time trains pass over it. After 50–60 years of millions of stress cycles, the structural steel suffers from severe elastic fatigue, reducing its elastic limit and fracture threshold. Therefore, bridges are retired to prevent catastrophic collapse under normal operational loads.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q52: Two Wires of Different Materials in Series: Equivalent Elongation</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A steel wire and a brass wire, both of equal length 1.5 m and diameter 2.0 mm, are connected end-to-end to form a composite wire of length 3.0 m. A tensile load of 100 N is applied. Find: (i) the elongation of each wire, and (ii) the total elongation. (Y_{steel} = 2.0 &times; 10<sup>11</sup> N/m<sup>2</sup>, Y_{brass} = 1.0 &times; 10<sup>11</sup> N/m<sup>2</sup>).</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Both wires carry the identical tension force F = 100 N because they are in series.<br/>\n    Common radius r = 1.0 mm = 10<sup>-3</sup> m &rArr; A = &pi; r<sup>2</sup> = 3.1416 &times; 10<sup>-6</sup> m<sup>2</sup>. Length L = 1.5 m.<br/>\n    <strong>(i) Elongations:</strong>\n    &Delta;L_s = (F &middot; L / A &middot; Y_s) = {100 &times; 1.5}{(3.1416 &times; 10<sup>-6</sup>) &times; (2.0 &times; 10<sup>11</sup>)} = {150}{6.2832 &times; 10<sup>5</sup>} &approx; 2.39 &times; 10<sup>-4</sup> m = 0.239 mm\n    &Delta;L_b = (F &middot; L / A &middot; Y_b) = {100 &times; 1.5}{(3.1416 &times; 10<sup>-6</sup>) &times; (1.0 &times; 10<sup>11</sup>)} = {150}{3.1416 &times; 10<sup>5</sup>} &approx; 4.77 &times; 10<sup>-4</sup> m = 0.477 mm\n    <strong>(ii) Total Elongation:</strong>\n    &Delta;L_{total} = &Delta;L_s + &Delta;L_b = 0.239 mm + 0.477 mm = 0.716 mm\n  </div>\n</div>\n\n<!-- FLUIDS SA QUESTIONS (Q53 to Q68) -->\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q53: Working Principle and Mechanical Advantage of a Hydraulic Lift</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Explain the working principle of a hydraulic lift using Pascal's law. If the area of the smaller piston is 5 cm<sup>2</sup> and that of the larger piston is 250 cm<sup>2</sup>, calculate the force required on the smaller piston to lift an automobile of mass 1500 kg (g = 9.8 m/s<sup>2</sup>).</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Principle:</b> A hydraulic lift operates on <strong>Pascal's Principle</strong>: any pressure applied to an enclosed incompressible fluid is transmitted equally and undiminished to every point of the fluid and the container walls.<br/>\n    Let force F_1 be applied to smaller piston of area A_1. The pressure generated is P_1 = F_1 / A_1. This pressure is transmitted to the larger piston of area A_2, producing upward lifting force:\n    F_2 = P_1 &times; A_2 = F_1 &times; ((A_2 / A_1))\n    The mechanical advantage is MA = (A_2 / A_1).<br/>\n    <b style=\"color: #FF007F;\">Numerical Calculation:</b><br/>\n    Weight to lift F_2 = mg = 1500 &times; 9.8 = 14,700 N.<br/>\n    Area ratio (A_2 / A_1) = {250 cm<sup>2</sup>}{5 cm<sup>2</sup>} = 50.<br/>\n    Force required on small piston:\n    F_1 = (F_2 / A_2 / A_1) = (14,700 / 50) = 294 N\n    Thus, a modest force of only <strong>294 N</strong> lifts a heavy 1500 kg automobile.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q54: Hydrostatic Pressure at the Bottom of Mariana Trench</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> The Mariana Trench is located in the Pacific Ocean at a depth of about 11.0 km below the water surface. If the average density of seawater is 1030 kg/m<sup>3</sup> and atmospheric pressure is 1.01 &times; 10<sup>5</sup> Pa, calculate: (i) the gauge pressure, and (ii) the absolute total pressure at this depth. (g = 9.8 m/s<sup>2</sup>).</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Given: Depth h = 11.0 km = 11,000 m, &rho; = 1030 kg/m<sup>3</sup>, P_{atm} = 1.01 &times; 10<sup>5</sup> Pa, g = 9.8 m/s<sup>2</sup>.<br/>\n    <strong>(i) Gauge Pressure (P_g):</strong>\n    P_g = &rho; g h = 1030 &times; 9.8 &times; 11,000 = 1.11034 &times; 10<sup>8</sup> Pa &approx; 1.11 &times; 10<sup>8</sup> Pa\n    <strong>(ii) Absolute Total Pressure (P):</strong>\n    P = P_{atm} + P_g = 1.01 &times; 10<sup>5</sup> + 1.11034 &times; 10<sup>8</sup> = 1.11135 &times; 10<sup>8</sup> Pa &approx; 1.11 &times; 10<sup>8</sup> Pa\n    Expressed in atmospheres (1 atm = 1.013 &times; 10<sup>5</sup> Pa):\n    P &approx; {1.11135 &times; 10<sup>8</sup>}{1.013 &times; 10<sup>5</sup>} &approx; 1097 atmospheres\n    This massive pressure is approximately 1100 times atmospheric pressure at sea level.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q55: U-Tube Manometer with Immiscible Liquids</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A U-tube contains water and methylated spirit separated by mercury. In one arm, a column of 10.0 cm of water is poured, and in the other arm, spirit is poured until the mercury surfaces in both arms are at the same horizontal level. If the spirit column height is 12.5 cm, determine the specific gravity (relative density) of the spirit.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Since the mercury surfaces in both limbs are at the identical horizontal level, the pressures exerted by the liquid columns on the two sides of the mercury must balance each other:<br/>\n    P_{water limb} = P_{spirit limb}\n    P_{atm} + h_w \\rho_w g = P_{atm} + h_s \\rho_s g\n    Subtracting atmospheric pressure P_{atm} and dividing by g:\n    h_w \\rho_w = h_s \\rho_s &rArr; (\\rho_s / \\rho_w) = (h_w / h_s)\n    Given h_w = 10.0 cm and h_s = 12.5 cm:\n    Specific Gravity of Spirit = (\\rho_s / \\rho_w) = (10.0 cm / 12.5 cm) = 0.80\n    Hence, the relative density of the methylated spirit is <strong>0.80</strong> (and its density is 800 kg/m<sup>3</sup>).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q56: Calculation of Terminal Velocity of a Falling Raindrop</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Calculate the terminal velocity of a spherical raindrop of radius 0.2 mm falling through air. The density of air is 1.2 kg/m<sup>3</sup>, density of water is 1000 kg/m<sup>3</sup>, viscosity of air is 1.8 &times; 10<sup>-5</sup> Pa&middot; s, and g = 9.8 m/s<sup>2</sup>.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Given: r = 0.2 mm = 2.0 &times; 10<sup>-4</sup> m, &rho; = 1000 kg/m<sup>3</sup>, &sigma; = 1.2 kg/m<sup>3</sup>, &eta; = 1.8 &times; 10<sup>-5</sup> Pa&middot; s.<br/>\n    Terminal velocity formula:\n    v_t = (2 / 9) {r<sup>2</sup>(&rho; - &sigma;)g}{&eta;}\n    Substituting the values:\n    v_t = (2 / 9) &times; {(2.0 &times; 10<sup>-4</sup>)<sup>2</sup> &times; (1000 - 1.2) &times; 9.8}{1.8 &times; 10<sup>-5</sup>}\n    v_t = (2 / 9) &times; {(4.0 &times; 10<sup>-8</sup>) &times; 998.8 &times; 9.8}{1.8 &times; 10<sup>-5</sup>} = {2 &times; 3.915 &times; 10<sup>-4</sup>}{1.62 &times; 10<sup>-4</sup>} &approx; 4.83 m/s\n    The terminal speed of the raindrop is approximately <strong>4.83 m/s</strong>.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q57: Reynolds Number and Prediction of Streamline vs Turbulent Flow</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Water flows through a horizontal pipe of internal diameter 2.0 cm at a rate of 3.0 liters per minute. Determine the speed of water and calculate the Reynolds number. Is the flow laminar, transition, or turbulent? (Take \\eta_{water} = 1.0 &times; 10<sup>-3</sup> Pa&middot; s, &rho; = 1000 kg/m<sup>3</sup>).</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Diameter D = 2.0 cm = 0.02 m, radius r = 0.01 m.<br/>\n    Cross-sectional area A = &pi; r<sup>2</sup> = 3.1416 &times; (0.01)<sup>2</sup> = 3.1416 &times; 10<sup>-4</sup> m<sup>2</sup>.<br/>\n    Volume flow rate Q = 3.0 L/min = {3.0 &times; 10<sup>-3</sup> m<sup>3</sup>}{60 s} = 5.0 &times; 10<sup>-5</sup> m<sup>3</sup>/s.<br/>\n    Speed of flow v = (Q / A) = {5.0 &times; 10<sup>-5</sup>}{3.1416 &times; 10<sup>-4</sup>} &approx; 0.159 m/s.<br/>\n    Reynolds number (R_e):\n    R_e = (&rho; v D / &eta;) = {1000 &times; 0.159 &times; 0.02}{1.0 &times; 10<sup>-3</sup>} = 3180\n    Since 2000 < R_e < 3000-4000, the flow is in the <strong>transition (unstable) regime</strong> between laminar streamline and turbulent flow.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q58: Venturimeter: Formula for Flow Speed and Volume Rate</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A horizontal pipeline of cross-sectional area 40 cm<sup>2</sup> carries water. At a constriction (throat), the cross-sectional area narrows to 20 cm<sup>2</sup>. A differential manometer connected between the main pipe and throat shows a height difference of 5.0 cm of water. Calculate the speed of water in the main pipe and the volume discharge rate (g = 9.8 m/s<sup>2</sup>).</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Let A_1 = 40 cm<sup>2</sup> = 4.0 &times; 10<sup>-3</sup> m<sup>2</sup>, A_2 = 20 cm<sup>2</sup> = 2.0 &times; 10<sup>-3</sup> m<sup>2</sup>.<br/>\n    Height difference in water manometer h = 5.0 cm = 0.05 m. Pressure difference P_1 - P_2 = &rho; g h.<br/>\n    From Bernoulli's theorem and equation of continuity (v_2 = (A_1 / A_2) v_1 = 2 v_1):\n    P_1 - P_2 = (1 / 2)&rho; (v_2<sup>2</sup> - v_1<sup>2</sup>) = (1 / 2)&rho; [(2v_1)<sup>2</sup> - v_1<sup>2</sup>] = (3 / 2)&rho; v_1<sup>2</sup>\n    Equating to &rho; g h:\n    &rho; g h = (3 / 2)&rho; v_1<sup>2</sup> &rArr; v_1 = &radic;{(2gh / 3)}\n    Substituting g = 9.8 m/s<sup>2</sup>, h = 0.05 m:\n    v_1 = &radic;{(2 &times; 9.8 &times; 0.05 / 3)} = &radic;{(0.98 / 3)} = &radic;(0.3267) &approx; 0.572 m/s\n    Volume discharge rate:\n    Q = A_1 v_1 = (4.0 &times; 10<sup>-3</sup>) &times; 0.572 &approx; 2.29 &times; 10<sup>-3</sup> m<sup>3</sup>/s = 2.29 L/s\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q59: Torricelli's Law of Efflux and Calculation of Liquid Range</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A tall cylindrical water tank open at the top has a small puncture hole of diameter 2 mm punched in its side wall at a depth of 4.9 m below the free water surface. Calculate: (i) the velocity of efflux of water escaping from the hole, and (ii) the volume of water flowing out per second (g = 9.8 m/s<sup>2</sup>).</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <strong>(i) Velocity of Efflux:</strong>\n    By Torricelli's Law, the speed of efflux from an open container orifice at depth h is:\n    v = &radic;(2gh) = &radic;(2 &times; 9.8 &times; 4.9) = &radic;(96.04) = 9.8 m/s\n    <strong>(ii) Volume Flow Rate:</strong>\n    Radius of hole r = 1 mm = 10<sup>-3</sup> m. Area a = &pi; r<sup>2</sup> = 3.1416 &times; 10<sup>-6</sup> m<sup>2</sup>.\n    Q = a &middot; v = (3.1416 &times; 10<sup>-6</sup>) &times; 9.8 &approx; 3.08 &times; 10<sup>-5</sup> m<sup>3</sup>/s = 30.8 cm<sup>3</sup>/s\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q60: Dynamic Lift on an Aeroplane Wing (Aerofoil) Explained by Bernoulli</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Explain how the aerodynamic shape of an airplane wing (aerofoil) produces upward dynamic lift during horizontal flight using Bernoulli's theorem.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    An airplane wing is designed with an asymmetric aerodynamic cross-section (aerofoil) where the upper surface is curved convexly while the lower surface is relatively flat.<br/>\n    1. During flight, air dividing at the leading edge travels faster over the curved upper surface than underneath the flatter lower surface (v_{top} > v_{bottom}).<br/>\n    2. According to <strong>Bernoulli's Equation</strong>:\n    P + (1 / 2)&rho; v<sup>2</sup> = constant\n    Regions of higher air speed experience lower static pressure. Consequently, static pressure on top of the wing drops below that under the bottom of the wing (P_{top} < P_{bottom}).<br/>\n    3. This net upward pressure difference &Delta;P = P_{bottom} - P_{top} acts over the total wing surface area A, generating an upward resultant aerodynamic force called <strong>dynamic lift</strong>:\n    F_{lift} = &Delta;P &middot; A = (1 / 2)&rho; (v_{top}<sup>2</sup> - v_{bottom}<sup>2</sup>) A\n    When dynamic lift equals the aircraft weight, level flight is maintained.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q61: Magnus Effect: Deviation in Path of a Spinning Ball</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> What is the Magnus effect? Explain with a neat conceptual explanation why a spinning cricket or tennis ball curves in mid-air away from its parabolic trajectory.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Magnus Effect:</b> The dynamic lateral force experienced by a spinning cylinder or sphere translating through a fluid, causing its trajectory to curve, is known as the <strong>Magnus Effect</strong>.<br/>\n    <b style=\"color: #FF007F;\">Mechanism:</b><br/>\n    1. When a ball spins with topspin while flying forward through air, friction between the rough ball surface and adjacent air drags a thin layer of air around with it.<br/>\n    2. On the top side of the ball, the rotational motion opposes the oncoming airstream, reducing the relative airspeed (v_{top} = v - v_{spin}).<br/>\n    3. On the bottom side, the rotational motion acts in the same direction as the oncoming airstream, accelerating the relative airspeed (v_{bottom} = v + v_{spin}).<br/>\n    4. By Bernoulli's principle, higher velocity on the bottom creates lower pressure, while lower velocity on the top creates higher pressure (P_{top} > P_{bottom}).<br/>\n    5. This downward pressure difference forces the ball to dip downwards much faster than gravity alone, producing sharp late dip (or lateral swerve in sideways swing bowling).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q62: Excess Pressure Inside Soap Bubble vs Water Drop Calculation</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Find the excess pressure inside: (i) a spherical water drop of radius 1.5 mm, and (ii) a soap bubble of the same radius. Take the surface tension of water as 0.075 N/m and that of soap solution as 0.030 N/m. Why does a soap bubble have double the factor in its excess pressure formula?</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Given: R = 1.5 mm = 1.5 &times; 10<sup>-3</sup> m, T_{water} = 0.075 N/m, T_{soap} = 0.030 N/m.<br/>\n    <strong>(i) Water Drop (1 free liquid-air interface):</strong>\n    &Delta;P_{drop} = {2T_{water}}{R} = {2 &times; 0.075}{1.5 &times; 10<sup>-3</sup>} = {0.150}{1.5 &times; 10<sup>-3</sup>} = 100 Pa\n    <strong>(ii) Soap Bubble (2 free liquid-air interfaces: inner and outer):</strong>\n    &Delta;P_{bubble} = {4T_{soap}}{R} = {4 &times; 0.030}{1.5 &times; 10<sup>-3</sup>} = {0.120}{1.5 &times; 10<sup>-3</sup>} = 80 Pa\n    <strong>Reason for Factor 4:</strong> A liquid drop is solid liquid inside with only one outer free surface. A soap bubble consists of a thin spherical liquid film enclosing an air pocket inside; thus it has <strong>two free liquid-air surfaces</strong> (inner and outer). Both surfaces contribute surface tension force, resulting in &Delta;P = (4T / R).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q63: Work Done in Blowing a Soap Bubble from Radius R_1 to R_2</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Calculate the work done in blowing a soap bubble of radius 2.0 cm to a radius of 4.0 cm. The surface tension of the soap solution is 0.030 N/m.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Given: R_1 = 2.0 cm = 0.02 m, R_2 = 4.0 cm = 0.04 m, T = 0.030 N/m.<br/>\n    A soap bubble has two free surfaces. Total surface area of a soap bubble of radius R is:\n    A = 2 &times; (4&pi; R<sup>2</sup>) = 8&pi; R<sup>2</sup>\n    Increase in surface area:\n    &Delta;A = 8&pi; (R_2<sup>2</sup> - R_1<sup>2</sup>) = 8&pi; [(0.04)<sup>2</sup> - (0.02)<sup>2</sup>] = 8&pi; [0.0016 - 0.0004] = 8&pi; &times; 0.0012 = 9.6&pi; &times; 10<sup>-3</sup> m<sup>2</sup>\n    Work done:\n    W = T &middot; &Delta;A = 0.030 &times; (9.6&pi; &times; 10<sup>-3</sup>) = 2.88&pi; &times; 10<sup>-4</sup> J &approx; 2.88 &times; 3.1416 &times; 10<sup>-4</sup> &approx; 9.05 &times; 10<sup>-4</sup> J\n    Hence, the work required is approximately <strong>9.05 &times; 10<sup>-4</sup> J</strong>.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q64: Energy Released When Small Droplets Coalesce into One Large Drop</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> One thousand (10<sup>3</sup>) identical mercury droplets, each of radius r = 1.0 mm, merge together to form a single large spherical drop. If surface tension of mercury is 0.465 N/m, calculate: (i) the radius of the large drop, and (ii) the energy released during coalescence.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Given: n = 1000 = 10<sup>3</sup>, r = 1.0 mm = 10<sup>-3</sup> m, T = 0.465 N/m.<br/>\n    <strong>(i) Radius of the Large Drop (R):</strong>\n    By conservation of volume:\n    (4 / 3)&pi; R<sup>3</sup> = n &middot; (4 / 3)&pi; r<sup>3</sup> &rArr; R = n<sup>1/3</sup> r = (1000)<sup>1/3</sup> &times; 10<sup>-3</sup> = 10 &times; 10<sup>-3</sup> m = 1.0 cm\n    <strong>(ii) Energy Released:</strong>\n    Initial surface area of n droplets: A_i = n(4&pi; r<sup>2</sup>) = 1000 &times; 4&pi; (10<sup>-3</sup>)<sup>2</sup> = 4&pi; &times; 10<sup>-3</sup> m<sup>2</sup>.<br/>\n    Final surface area of single drop: A_f = 4&pi; R<sup>2</sup> = 4&pi; (10<sup>-2</sup>)<sup>2</sup> = 4&pi; &times; 10<sup>-4</sup> m<sup>2</sup>.<br/>\n    Decrease in surface area:\n    &Delta;A = A_i - A_f = 4&pi; (10<sup>-3</sup> - 10<sup>-4</sup>) = 4&pi; (9 &times; 10<sup>-4</sup>) = 3.6&pi; &times; 10<sup>-3</sup> m<sup>2</sup>\n    Energy released as heat:\n    E_{released} = T &middot; &Delta;A = 0.465 &times; (3.6&pi; &times; 10<sup>-3</sup>) &approx; 0.465 &times; 0.01131 &approx; 5.26 &times; 10<sup>-3</sup> J\n    This released surface energy slightly warms the mercury drop.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q65: Capillary Rise: Calculation of Height in a Glass Tube</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A capillary tube of bore diameter 0.4 mm is dipped vertically into a beaker of clean water. Find the height to which water will rise in the tube. Take T_{water} = 0.073 N/m, contact angle &theta; = 0<sup>&deg;</sup>, &rho; = 1000 kg/m<sup>3</sup>, and g = 9.8 m/s<sup>2</sup>. What happens if the tube is pushed down until only 2.0 cm remains above the water level?</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Bore diameter 2r = 0.4 mm &rArr; r = 0.2 mm = 2.0 &times; 10<sup>-4</sup> m.<br/>\n    Capillary ascent formula:\n    h = (2T\\cos&theta; / r&rho; g) = {2 &times; 0.073 &times; \\cos(0<sup>&deg;</sup>)}{(2.0 &times; 10<sup>-4</sup>) &times; 1000 &times; 9.8} = (0.146 / 1.96) &approx; 0.0745 m = 7.45 cm\n    <b style=\"color: #FF007F;\">Insufficient Length Case:</b> If the tube of length only 2.0 cm is provided (l < h), <strong>water will NOT overflow</strong> out of the top. Instead, water rises to the very rim (2.0 cm) and the radius of curvature R of the concave meniscus increases (h &middot; R = constant), making the meniscus flatter (cos&theta;' decreases) so that:\n    h' R' = h R &rArr; R' = (h / h') R\n    The water meniscus adjusts its curvature to balance the hydrostatic pressure without overflowing.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q66: Explain Why Detergents and Soaps Clean Clothes Effectively</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Water alone cannot easily remove oily grease and dirt from clothes. Explain how the addition of detergents dramatically improves washing efficiency in terms of surface tension and angle of contact.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    1. <strong>Reduction of Surface Tension:</strong> Pure water has a relatively high surface tension (0.073 N/m) due to strong hydrogen bonding. It prefers to form spherical droplets rather than spreading. Detergent molecules are surfactants that disrupt hydrogen bonds, reducing surface tension to below 0.030 N/m.<br/>\n    2. <strong>Reduction of Contact Angle:</strong> Detergents make the contact angle &theta; between water and fabric fibers acute (close to 0<sup>&deg;</sup>). This drastically enhances the wetting power, enabling water to penetrate narrow capillary pores between fabric threads.<br/>\n    3. <strong>Micelle Action:</strong> Detergent molecules have hydrophobic non-polar hydrocarbon tails that attach to oil/grease and hydrophilic ionic heads that face the water. During agitation, oil droplets are broken into tiny suspended droplets (micelles) that are rinsed away with water.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q67: Why Do Small Raindrops Fall Slowly While Large Hailstones Fall Fast?</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Using the formula for terminal velocity, explain why tiny cloud droplets stay floating in the air for hours while large hailstones crash to the ground with destructive speeds.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    The terminal velocity of a falling spherical body is given by:\n    v_t = (2 / 9){r<sup>2</sup>(&rho; - &sigma;)g}{&eta;} &prop; r<sup>2</sup>\n    From this relation, terminal speed depends directly on the <strong>square of the radius (r<sup>2</sup>)</strong>:<br/>\n    1. A microscopic cloud droplet has radius r &approx; 10 &mu;m = 10<sup>-5</sup> m. Its terminal velocity is negligibly small (v_t &approx; 0.01 m/s = 1 cm/s); gentle thermal updrafts easily keep it suspended as a cloud.<br/>\n    2. A large hailstone of radius r &approx; 1.0 cm = 10<sup>-2</sup> m is 1000 times larger in radius. Since v_t &prop; r<sup>2</sup>, its terminal velocity is (1000)<sup>2</sup> = 10<sup>6</sup> times greater, reaching over 30 to 40 m/s (110 to 140 km/h), causing severe damage upon impact.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q68: Bernoulli's Principle in Action: Atomizer / Paint Sprayer</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Describe the working of an atomizer (or scent spray / paint gun) based on Bernoulli's theorem.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    1. An atomizer consists of a squeeze rubber bulb, a horizontal constriction tube (nozzle), and a vertical suction tube dipping into a perfume or paint container.<br/>\n    2. When the bulb is squeezed, a high-velocity jet of air shoots rapidly through the narrow horizontal nozzle (v_{air} is very high).<br/>\n    3. By Bernoulli's equation (P + (1 / 2)&rho; v<sup>2</sup> = constant), this high speed creates a localized drop in static pressure (P < P_{atm}) directly over the top opening of the vertical tube.<br/>\n    4. Since atmospheric pressure P_{atm} acts continuously on the liquid surface in the container, the higher external pressure pushes the liquid up the tube into the air stream.<br/>\n    5. The fast-moving air blast instantly shears the emerging liquid column into a fine misty spray of microscopic droplets.\n  </div>\n</div>\n\n<!-- THERMAL SA QUESTIONS (Q69 to Q80) -->\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q69: Thermal Stress in a Clamped Rod Prevented from Expanding</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A steel rod of cross-sectional area 4.0 cm<sup>2</sup> and length 1.0 m is clamped rigidly at both ends at a temperature of 20<sup>&deg;</sup>C. If the temperature is raised to 60<sup>&deg;</sup>C, calculate the compressive thermal stress and the force exerted on the rigid clamps. (Y_{steel} = 2.0 &times; 10<sup>11</sup> N/m<sup>2</sup>, \\alpha_{steel} = 1.2 &times; 10<sup>-5</sup> K<sup>-1</sup>).</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Given: A = 4.0 cm<sup>2</sup> = 4.0 &times; 10<sup>-4</sup> m<sup>2</sup>, &Delta;T = 60 - 20 = 40<sup>&deg;</sup>C = 40 K.<br/>\n    If the rod were free to expand, its thermal expansion would be &Delta;L = L &alpha; &Delta;T.<br/>\n    Since rigid clamps prevent this expansion, thermal strain developed is:\n    \\epsilon = (&Delta;L / L) = &alpha; &Delta;T = (1.2 &times; 10<sup>-5</sup>) &times; 40 = 4.8 &times; 10<sup>-4</sup>\n    Compressive Thermal Stress:\n    &sigma; = Y &middot; \\epsilon = Y &alpha; &Delta;T = (2.0 &times; 10<sup>11</sup>) &times; (4.8 &times; 10<sup>-4</sup>) = 9.6 &times; 10<sup>7</sup> N/m<sup>2</sup>\n    Force exerted on the clamps:\n    F = &sigma; &middot; A = (9.6 &times; 10<sup>7</sup>) &times; (4.0 &times; 10<sup>-4</sup>) = 3.84 &times; 10<sup>4</sup> N = 38.4 kN\n    This massive force of 38.4 kN illustrates why expansion gaps and rollers must be provided in railway tracks and steel bridges.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q70: Working of a Bimetallic Strip and Its Thermostatic Applications</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> What is a bimetallic strip? Explain how it bends when heated and when cooled. Mention two practical applications.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    A bimetallic strip consists of two equal strips of different metals (such as brass and invar/iron) riveted together tightly along their length.<br/>\n    1. <strong>Upon Heating:</strong> Brass expands much more than iron (\\alpha_{brass} > \\alpha_{iron}). Because the strips are bonded, the composite strip curves into an arc with the higher-expanding metal (brass) on the outer convex side and the lower-expanding metal on the inner concave side.<br/>\n    2. <strong>Upon Cooling:</strong> Brass contracts more than iron; consequently, the strip bends in the opposite direction with brass on the inner concave curve.<br/>\n    <b style=\"color: #FF007F;\">Applications:</b><br/>\n    - <strong>Thermostats:</strong> In electric irons, geysers, and refrigerators to automatically make or break the electric circuit when preset temperatures are reached.<br/>\n    - <strong>Fire Alarms:</strong> Heat bends the strip to touch a contact screw, completing the bell circuit to trigger the alarm.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q71: Derivation of the Relation Between &alpha; and &beta; (&beta; = 2&alpha;)</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Derive the mathematical relationship between the coefficient of linear expansion (&alpha;) and superficial (areal) expansion (&beta;) of an isotropic solid.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Consider a square sheet of an isotropic solid of side L_0 at 0<sup>&deg;</sup>C. Its initial area is A_0 = L_0<sup>2</sup>.<br/>\n    When heated by temperature &Delta;T, the side becomes:\n    L = L_0 (1 + &alpha; &Delta;T)\n    The expanded area A is:\n    A = L<sup>2</sup> = L_0<sup>2</sup>(1 + &alpha; &Delta;T)<sup>2</sup> = A_0 (1 + 2&alpha; &Delta;T + &alpha;<sup>2</sup> &Delta;T<sup>2</sup>)\n    Since &alpha; is on the order of 10<sup>-5</sup> K<sup>-1</sup>, the second-order term &alpha;<sup>2</sup>&Delta;T<sup>2</sup> is extremely small (order 10<sup>-10</sup>) and can be safely neglected:<br/>\n    A &approx; A_0 (1 + 2&alpha; &Delta;T)\n    By definition of coefficient of superficial expansion:\n    A = A_0 (1 + &beta; &Delta;T)\n    Comparing the two expressions gives directly:\n    &beta; = 2&alpha;\n    Thus, the coefficient of superficial expansion is exactly double the coefficient of linear expansion.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q72: Derivation of the Relation Between &alpha; and &gamma; (&gamma; = 3&alpha;)</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Derive the relation between the coefficient of linear expansion (&alpha;) and coefficient of cubical (volume) expansion (&gamma;). Hence show that &alpha; : &beta; : &gamma; = 1 : 2 : 3.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Consider a cube of an isotropic solid of edge L_0 at 0<sup>&deg;</sup>C. Its initial volume is V_0 = L_0<sup>3</sup>.<br/>\n    When temperature is raised by &Delta;T, each edge expands to L = L_0 (1 + &alpha; &Delta;T).<br/>\n    The new volume V is:\n    V = L<sup>3</sup> = L_0<sup>3</sup>(1 + &alpha; &Delta;T)<sup>3</sup> = V_0 (1 + 3&alpha; &Delta;T + 3&alpha;<sup>2</sup> &Delta;T<sup>2</sup> + &alpha;<sup>3</sup> &Delta;T<sup>3</sup>)\n    Neglecting higher powers &alpha;<sup>2</sup> and &alpha;<sup>3</sup> because &alpha; &ll; 1:\n    V &approx; V_0 (1 + 3&alpha; &Delta;T)\n    By definition of cubical expansion:\n    V = V_0 (1 + &gamma; &Delta;T)\n    Comparing coefficients yields:\n    &gamma; = 3&alpha;\n    Combining the results:\n    &alpha; = &alpha;, \\quad &beta; = 2&alpha;, \\quad &gamma; = 3&alpha; &rArr; &alpha; : &beta; : &gamma; = 1 : 2 : 3\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q73: Calorimetry: Ice at 0°C Added to Warm Water Calculation</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> 50 g of ice at 0<sup>&deg;</sup>C is placed in a calorimeter containing 200 g of water at 30<sup>&deg;</sup>C. Neglecting the heat capacity of the calorimeter, find the final equilibrium temperature of the mixture. (Take L_f = 336 J/g and c_{water} = 4.186 J/g&middot; <sup>&deg;</sup>C).</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Heat required to melt all 50 g of ice into water at 0<sup>&deg;</sup>C:\n    Q_1 = m_{ice} L_f = 50 &times; 336 = 16,800 J\n    Maximum heat available from warm water cooling from 30<sup>&deg;</sup>C to 0<sup>&deg;</sup>C:\n    Q_{avail} = m_w c_w &Delta;T = 200 &times; 4.186 &times; 30 = 25,116 J\n    Since Q_{avail} > Q_1, all the ice melts completely and the final equilibrium temperature T lies between 0<sup>&deg;</sup>C and 30<sup>&deg;</sup>C.<br/>\n    By Principle of Calorimetry (Heat gained = Heat lost):\n    m_{ice} L_f + m_{ice} c_w (T - 0) = m_w c_w (30 - T)\n    16,800 + 50 &times; 4.186 &times; T = 25,116 - 200 &times; 4.186 &times; T\n    16,800 + 209.3 T = 25,116 - 837.2 T\n    (209.3 + 837.2) T = 25,116 - 16,800\n    1046.5 T = 8316 &rArr; T = (8316 / 1046.5) &approx; 7.95<sup>&deg;</sup>C\n    The final equilibrium temperature of the mixture is approximately <strong>7.95<sup>&deg;</sup>C</strong>.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q74: Why is Steam at 100°C More Severe than Boiling Water at 100°C?</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Burns caused by steam at 100<sup>&deg;</sup>C are substantially more severe and painful than burns caused by liquid water at 100<sup>&deg;</sup>C. Explain the thermodynamics behind this observation with quantitative values.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Even though both steam and boiling water are at the identical temperature of 100<sup>&deg;</sup>C:<br/>\n    1. <strong>Latent Heat of Vaporization:</strong> When 1 g of boiling water at 100<sup>&deg;</sup>C contacts skin and cools to body temperature (37<sup>&deg;</sup>C), it releases only sensible heat:\n    Q_{water} = m c &Delta;T = 1 &times; 4.186 &times; (100 - 37) &approx; 263.7 J\n    2. In contrast, 1 g of steam at 100<sup>&deg;</sup>C must first condense into water at 100<sup>&deg;</sup>C, releasing its immense <strong>latent heat of vaporization</strong>:\n    L_v = 2260 J/g\n    Then the resulting hot water at 100<sup>&deg;</sup>C further cools down to 37<sup>&deg;</sup>C, releasing another 263.7 J.<br/>\n    Total heat released by 1 g steam:\n    Q_{steam} = 2260 + 263.7 = 2523.7 J\n    Steam delivers nearly <strong>10 times more thermal energy</strong> per gram to biological tissue, causing deep thermal destruction and severe second-degree scalds.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q75: Steady State Heat Conduction Through a Compound Bar (Series)</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Two slabs of equal thickness d and equal cross-sectional area A are placed in series thermal contact. Their thermal conductivities are K_1 and K_2. The outer face of slab 1 is maintained at temperature T_1 and the outer face of slab 2 at T_2 (T_1 > T_2). Find: (i) the interface temperature T, and (ii) the equivalent thermal conductivity K_{eq} of the composite slab.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    In steady state, the rate of heat flow H through both slabs in series is identical:<br/>\n    H = (K_1 A (T_1 - T) / d) = (K_2 A (T - T_2) / d)\n    Equating the two:\n    K_1(T_1 - T) = K_2(T - T_2) &rArr; K_1 T_1 + K_2 T_2 = (K_1 + K_2)T\n    <strong>(i) Interface Temperature:</strong>\n    T = (K_1 T_1 + K_2 T_2 / K_1 + K_2)\n    <strong>(ii) Equivalent Thermal Conductivity (K_{eq}):</strong>\n    Total thickness is 2d. Thermal resistance of two slabs in series:\n    R_{total} = R_1 + R_2 &rArr; {2d}{K_{eq} A} = (d / K_1 A) + (d / K_2 A)\n    {2}{K_{eq}} = (1 / K_1) + (1 / K_2) = (K_1 + K_2 / K_1 K_2) &rArr; K_{eq} = (2 K_1 K_2 / K_1 + K_2)\n    The equivalent thermal conductivity is the <strong>harmonic mean</strong> of the individual conductivities.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q76: Wien's Displacement Law: Calculation of Sun's Surface Temperature</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> State Wien's displacement law. The solar spectrum exhibits a maximum spectral emissive power at wavelength \\lambda_{\\max} = 490 nm (in the green-yellow region). Calculate the effective surface temperature of the Sun. (Wien's constant b = 2.898 &times; 10<sup>-3</sup> m&middot; K).</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Wien's Displacement Law:</b> The wavelength \\lambda_{\\max} corresponding to peak radiant emission of a blackbody is inversely proportional to its absolute thermodynamic temperature T:\n    \\lambda_{\\max} &middot; T = b = constant = 2.898 &times; 10<sup>-3</sup> m&middot; K\n    As temperature increases, the peak shifts (\"displaces\") toward shorter wavelengths.<br/>\n    <b style=\"color: #FF007F;\">Calculation:</b><br/>\n    Given \\lambda_{\\max} = 490 nm = 490 &times; 10<sup>-9</sup> m = 4.90 &times; 10<sup>-7</sup> m.\n    T = {b}{\\lambda_{\\max}} = {2.898 &times; 10<sup>-3</sup> m&middot; K}{4.90 &times; 10<sup>-7</sup> m} &approx; 5914 K\n    The effective surface temperature of the Sun is approximately <strong>5914 K</strong> (or &approx; 5640<sup>&deg;</sup>C).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q77: Stefan-Boltzmann Law: Radiant Heat Loss of a Hot Spherical Body</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> A spherical blackbody of radius 5.0 cm is maintained at a temperature of 500<sup>&deg;</sup>C in an evacuated enclosure whose walls are kept at 27<sup>&deg;</sup>C. Calculate: (i) the total radiant power emitted, and (ii) the net rate of heat loss from the sphere. (Take &sigma; = 5.67 &times; 10<sup>-8</sup> W/m<sup>2</sup>&middot; K<sup>4</sup>).</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Absolute temperature of body T = 500 + 273 = 773 K.<br/>\n    Absolute temperature of enclosure T_0 = 27 + 273 = 300 K.<br/>\n    Surface area of sphere:\n    A = 4&pi; r<sup>2</sup> = 4&pi; (0.05)<sup>2</sup> = 0.01&pi; m<sup>2</sup> &approx; 3.1416 &times; 10<sup>-2</sup> m<sup>2</sup>\n    <strong>(i) Total Radiant Power Emitted:</strong>\n    P_{emit} = &sigma; A T<sup>4</sup> = (5.67 &times; 10<sup>-8</sup>) &times; (3.1416 &times; 10<sup>-2</sup>) &times; (773)<sup>4</sup>\n    Since (773)<sup>4</sup> &approx; 3.57 &times; 10<sup>11</sup>:\n    P_{emit} &approx; 5.67 &times; 10<sup>-8</sup> &times; 0.031416 &times; 3.57 &times; 10<sup>11</sup> &approx; 636 W\n    <strong>(ii) Net Rate of Heat Loss:</strong>\n    P_{net} = &sigma; A (T<sup>4</sup> - T_0<sup>4</sup>) = (5.67 &times; 10<sup>-8</sup>) &times; (0.031416) &times; [(773)<sup>4</sup> - (300)<sup>4</sup>]\n    Since (300)<sup>4</sup> = 8.1 &times; 10<sup>9</sup> = 0.081 &times; 10<sup>11</sup>:\n    P_{net} &approx; 1.781 &times; 10<sup>-9</sup> &times; (3.57 &times; 10<sup>11</sup> - 0.081 &times; 10<sup>11</sup>) = 1.781 &times; 10<sup>-9</sup> &times; 3.489 &times; 10<sup>11</sup> &approx; 621 W\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q78: Qualitative Features of Blackbody Radiation Spectrum</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Describe the four fundamental experimental characteristics of the blackbody radiation spectral curves (E_&lambda; versus &lambda;) discovered by Lummer and Pringsheim.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    The experimental curves plotted by Lummer and Pringsheim reveal:<br/>\n    1. <strong>Continuous Spectrum:</strong> Thermal radiation is emitted across all continuous wavelengths from 0 to &infin;, but energy is distributed non-uniformly across wavelengths.<br/>\n    2. <strong>Pronounced Peak:</strong> For each temperature, radiant energy E_&lambda; rises to a distinct maximum (E_{\\max}) at a specific wavelength \\lambda_{\\max} and then drops asymptotically towards zero at longer wavelengths.<br/>\n    3. <strong>Wien's Shift:</strong> As the temperature of the blackbody rises, the peak wavelength \\lambda_{\\max} shifts monotonically toward shorter wavelengths (higher frequencies), satisfying \\lambda_{\\max} T = constant.<br/>\n    4. <strong>Stefan-Boltzmann Total Energy Growth:</strong> The total radiant energy emitted per second per unit area (represented by the total area under the E_&lambda; - &lambda; curve) increases drastically with absolute temperature, proportional to T<sup>4</sup> (Area = \\int_0<sup>&infin;</sup> E_&lambda; d&lambda; = &sigma; T<sup>4</sup>).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q79: Anomalous Expansion of Water: Density Maximum at 4°C</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Explain what is meant by the anomalous expansion of water between 0<sup>&deg;</sup>C and 4<sup>&deg;</sup>C. Why does the coefficient of cubical expansion &gamma; of water become negative in this range?</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    Almost all normal liquids continuously expand when heated, increasing in volume and decreasing in density.<br/>\n    <b style=\"color: #FF007F;\">Anomalous Behavior:</b> Water exhibits an extraordinary anomaly between 0<sup>&deg;</sup>C and 4<sup>&deg;</sup>C:<br/>\n    1. When liquid water at 0<sup>&deg;</sup>C is heated, its volume continuously <strong>contracts</strong> until it reaches a sharp minimum volume at 4<sup>&deg;</sup>C.<br/>\n    2. Consequently, water achieves its <strong>maximum density (1.000 g/cm<sup>3</sup> = 1000 kg/m<sup>3</sup>) at exactly 4<sup>&deg;</sup>C</strong>.<br/>\n    3. Only above 4<sup>&deg;</sup>C does water resume standard liquid behavior and expand with rising temperature.<br/>\n    <b style=\"color: #FF007F;\">Negative &gamma;:</b> Since volume decreases with increasing temperature between 0<sup>&deg;</sup>C and 4<sup>&deg;</sup>C (&Delta;V / &Delta;T < 0), the coefficient of volume expansion &gamma; = (1 / V)(&Delta;V / &Delta;T) is strictly <strong>negative</strong> in this interval.<br/>\n    <b style=\"color: #FF007F;\">Molecular Origin:</b> Ice has an open cage-like hexagonal crystal structure due to tetrahedral hydrogen bonds. When ice melts at 0<sup>&deg;</sup>C, some cages collapse, packing molecules closer together. Between 0<sup>&deg;</sup>C and 4<sup>&deg;</sup>C, the collapse of cage structures dominates over normal thermal vibrational expansion.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q80: Why Cooking in a Pressure Cooker is Faster at High Altitudes</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Cooking pulses and vegetables in an open pot is extremely difficult and slow at high altitudes (e.g., in Leh or Mount Everest base camp), but a pressure cooker cooks quickly even on mountain tops. Explain this using phase equilibria and vapor pressure concepts.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    1. <strong>Definition of Boiling Point:</strong> A liquid boils when its saturated vapor pressure equals the surrounding external atmospheric pressure.<br/>\n    2. <strong>High Altitude Open Cooking:</strong> At high altitudes, atmospheric pressure drops significantly (e.g., to &approx; 70 kPa at 3000 m). Consequently, water reaches vapor pressure equality and boils at a much lower temperature (around 88<sup>&deg;</sup>C to 90<sup>&deg;</sup>C). Because boiling is an isothermal process, no matter how much heat is supplied, the water temperature never rises above 90<sup>&deg;</sup>C. Chemical cooking reactions proceed very slowly at this lower temperature.<br/>\n    3. <strong>Pressure Cooker Action:</strong> A pressure cooker has a sealed lid with a weighted valve that traps steam. The internal pressure builds up to about 2 atmospheres (200 kPa). At this elevated pressure, the boiling point of water is forced up to approximately 120<sup>&deg;</sup>C to 125<sup>&deg;</sup>C. The substantially hotter water and steam transfer heat rapidly, cooking food in a fraction of the time.\n  </div>\n</div>\n\n  \n<!-- SECTION C: LONG ANSWER (LA) QUESTIONS (5 MARKS) (Q81 TO Q100) -->\n<div style=\"margin-top: 35px; margin-bottom: 20px; padding-bottom: 10px; border-bottom: 2px solid #FF007F;\">\n  <h2 style=\"color: #FF007F; font-size: 20px; margin: 0;\">SECTION C: LONG ANSWER (LA) QUESTIONS (5 MARKS)</h2>\n  <p style=\"color: #94A3B8; font-size: 13px; margin: 4px 0 0 0;\">Rigorous step-by-step mathematical proofs, full derivations, comprehensive theoretical frameworks, and board exam derivations across Unit VII.</p>\n</div>\n\n<!-- SOLIDS LA DERIVATIONS (Q81 & Q82) -->\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q81: Complete Stress-Strain Curve for a Metallic Wire Under Tensile Load</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Draw a typical stress versus strain curve for a ductile metallic wire (e.g., mild steel) subjected to an increasing tensile load up to fracture. Clearly identify, mark, and explain the physical significance of all five critical regions and landmark points: (i) Proportional limit, (ii) Elastic limit / Yield point, (iii) Permanent set, (iv) Ultimate tensile strength, and (v) Fracture point.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    When a uniform metallic wire of length L and area A is subjected to gradually increasing tensile tension, the experimental relationship between tensile stress (&sigma; = F/A) and tensile strain (\\epsilon = &Delta;L/L) displays five characteristic stages:<br/><br/>\n    <b style=\"color: #FF007F;\">1. Region OA (Linear Hooke's Law Region & Proportional Limit A):</b><br/>\n    - From origin O to point A, the stress-strain curve is a straight line passing through origin.<br/>\n    - In this region, <strong>Hooke's Law is strictly obeyed</strong>: Stress &prop; Strain, and the slope of line OA represents Young's modulus (Y = &sigma; / \\epsilon).<br/>\n    - Point A is called the <strong>Proportionality Limit</strong>. Maximum stress up to which stress remains strictly proportional to strain.<br/><br/>\n    <b style=\"color: #FF007F;\">2. Region AB (Elastic Region & Yield Point B):</b><br/>\n    - From A to B, stress is no longer proportional to strain (curve bends slightly), but the material remains completely <strong>elastic</strong>.<br/>\n    - If the deforming load is completely removed at or before point B, the wire retraces its path and returns exactly to its original length L with zero permanent deformation.<br/>\n    - Point B is the <strong>Elastic Limit</strong> (or Upper Yield Point). The stress corresponding to point B is termed the <strong>Yield Strength</strong> (\\sigma_y) of the metal.<br/><br/>\n    <b style=\"color: #FF007F;\">3. Region BC (Plastic Deformation & Permanent Set):</b><br/>\n    - If load is increased beyond B, strain increases much faster than stress.<br/>\n    - If the deforming force is removed at point C, the wire does <strong>not</strong> retrace its path to origin O. Instead, it recovers along the parallel dotted line CO', leaving a permanent residual elongation OO' known as a <strong>permanent set</strong> (typically 0.1\\% to 0.2\\% plastic strain).<br/>\n    - In this plastic regime, planes of metal atoms slip permanently over one another via dislocation movement.<br/><br/>\n    <b style=\"color: #FF007F;\">4. Region CD (Strain Hardening & Ultimate Tensile Strength D):</b><br/>\n    - Beyond C, the material undergoes extensive plastic flow. Atomic dislocations interact, requiring higher stress to produce further deformation (strain hardening).<br/>\n    - Point D represents the highest point on the curve, called the <strong>Ultimate Tensile Strength (UTS)</strong> (\\sigma_u). It is the maximum nominal stress the material can endure before localized thinning begins.<br/><br/>\n    <b style=\"color: #FF007F;\">5. Region DE (Necking and Fracture Point E):</b><br/>\n    - Beyond point D, localized cross-sectional thinning (\"necking\" or constriction) develops rapidly at a weak section.<br/>\n    - Even if the external applied force is decreased, the local stress at the constriction spikes until the wire snaps cleanly at point E, the <strong>Fracture Point</strong> (Breaking Point).<br/>\n    - If the plastic region B to E is wide, the material is <strong>ductile</strong>. If E lies immediately next to B, the material is <strong>brittle</strong>.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q82: Calculus Derivation of Elastic Potential Energy and Energy Density</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Using integral calculus, derive an expression for the elastic potential energy stored in a stretched wire of length L and cross-sectional area A when extended by an amount &Delta;L. Hence deduce that the energy stored per unit volume is equal to (1 / 2) &times; stress &times; strain = (1 / 2) Y (strain)<sup>2</sup>.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Step 1: Restoring Force at Intermediate Extension x:</b><br/>\n    Consider a wire of original length L and uniform cross-sectional area A made of a material having Young's modulus Y.<br/>\n    Let an external stretching force extend the wire by an intermediate elongation x (0 &le; x &le; &Delta;L).<br/>\n    Tensile strain at this state is \\epsilon = (x / L).<br/>\n    By Hooke's Law, the internal restoring force F is:\n    Y = (F / A / x / L) = (F &middot; L / A &middot; x) &rArr; F = (Y A / L) x\n    <b style=\"color: #FF007F;\">Step 2: Work Done for Additional Infinitesimal Extension dx:</b><br/>\n    To increase the elongation by an infinitesimal amount dx against this restoring force, the work done dW is:\n    dW = F &middot; dx = ((Y A / L) x) dx\n    <b style=\"color: #FF007F;\">Step 3: Total Work Done (Elastic Potential Energy U):</b><br/>\n    The total work done in stretching the wire from initial elongation x = 0 to final elongation x = &Delta;L is obtained by integration:\n    U = \\int_0<sup>&Delta;L</sup> dW = \\int_0<sup>&Delta;L</sup> ((Y A / L) x) dx = (Y A / L) [ {x<sup>2</sup>}{2} ]_0<sup>&Delta;L</sup> = (1 / 2) (Y A / L) (&Delta;L)<sup>2</sup>\n    Rewriting the terms:\n    U = (1 / 2) ( (Y A &Delta;L / L) ) &Delta;L = (1 / 2) F_{final} &middot; &Delta;L\n    \\mathbf{U = (1 / 2) F &middot; &Delta;L}\n    <b style=\"color: #FF007F;\">Step 4: Energy Stored Per Unit Volume (Energy Density u):</b><br/>\n    The total volume of the wire is V = A &middot; L.<br/>\n    Dividing total energy U by volume V:\n    u = (U / V) = ((1 / 2) F &middot; &Delta;L / A &middot; L) = (1 / 2) ( (F / A) ) ( (&Delta;L / L) )\n    Since (F / A) = Stress and (&Delta;L / L) = Strain:\n    \\mathbf{u = (1 / 2) &times; Stress &times; Strain}\n    Since Stress = Y &times; Strain, we also have:\n    \\mathbf{u = (1 / 2) Y (Strain)<sup>2</sup> = (1 / 2) {(Stress)<sup>2</sup>}{Y}}\n    This elastic potential energy represents the work done against interatomic electromagnetic forces and is completely recovered when the load is removed.\n  </div>\n</div>\n\n<!-- FLUIDS LA DERIVATIONS (Q83 to Q93) -->\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q83: State and Prove Pascal's Law for Transmission of Fluid Pressure</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> State Pascal's law of transmission of fluid pressure. Prove it rigorously by considering the equilibrium of a tiny right-triangular prismatic fluid element at rest inside the fluid. Derive the mechanical advantage formula of a hydraulic lift.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Statement:</b> Pascal's law states that whenever an external pressure is applied at any point of an enclosed, incompressible fluid at rest, this pressure is transmitted undiminished and equally in all directions throughout the fluid and to the walls of the containing vessel.<br/><br/>\n    <b style=\"color: #FF007F;\">Proof (Prismatic Element):</b><br/>\n    1. Consider an infinitesimal right-triangular prism-shaped fluid element of width b perpendicular to the page, with rectangular faces ABFE (area A_a), CDEF (area A_b), and slanted face ABCD (area A_c).<br/>\n    2. Let the fluid pressures acting normally on these faces be P_a, P_b, P_c.<br/>\n    3. The forces acting normal to the three faces are:\n    F_a = P_a A_a, \\quad F_b = P_b A_b, \\quad F_c = P_c A_c\n    4. By geometry, if angle of the wedge is &theta;:\n    A_a = A_c \\sin&theta;, \\quad A_b = A_c \\cos&theta;\n    5. Since the fluid element is in static equilibrium, net horizontal and net vertical forces must each be zero:<br/>\n    - Horizontal equilibrium:\n    F_a - F_c \\sin&theta; = 0 &rArr; P_a A_a = P_c A_c \\sin&theta;\n    Substituting A_a = A_c \\sin&theta;:\n    P_a (A_c \\sin&theta;) = P_c A_c \\sin&theta; &rArr; P_a = P_c\n    - Vertical equilibrium (ignoring weight of infinitesimal element):\n    F_b - F_c \\cos&theta; = 0 &rArr; P_b A_b = P_c A_c \\cos&theta;\n    Substituting A_b = A_c \\cos&theta;:\n    P_b (A_c \\cos&theta;) = P_c A_c \\cos&theta; &rArr; P_b = P_c\n    6. Equating both results:\n    P_a = P_b = P_c\n    Since the orientation &theta; of the prismatic element is completely arbitrary, pressure at any given point in a static fluid is <strong>isotropic (identical in all directions)</strong>.<br/><br/>\n    <b style=\"color: #FF007F;\">Hydraulic Lift Mechanical Advantage:</b><br/>\n    For two pistons of areas A_1 (small) and A_2 (large) connected by a fluid tube, an applied force F_1 generates pressure P = F_1 / A_1. Transmission of this pressure produces output force F_2 = P A_2 = F_1 (A_2 / A_1).<br/>\n    The mechanical advantage is:\n    MA = (F_2 / F_1) = (A_2 / A_1) = ((D_2 / D_1))<sup>2</sup>\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q84: Variation of Fluid Pressure with Depth and Hydrostatic Paradox</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Derive an expression for the variation of hydrostatic pressure with depth h in a static fluid of uniform density &rho; under gravity. Clearly define gauge pressure versus absolute pressure, and resolve the famous \"Hydrostatic Paradox\".</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Derivation:</b><br/>\n    1. Consider a static fluid of uniform density &rho; in a container under gravity g.<br/>\n    2. Imagine an imaginary vertical cylindrical fluid element of cross-sectional area A and height h, with its top face at depth y_1 (pressure P_1) and bottom face at depth y_2 (pressure P_2), such that y_2 - y_1 = h.<br/>\n    3. The forces acting on this vertical fluid cylinder are:<br/>\n       - Downward force on top face: F_1 = P_1 A<br/>\n       - Upward force on bottom face: F_2 = P_2 A<br/>\n       - Downward gravitational weight of fluid: W = m g = (&rho; &middot; V) g = (&rho; A h) g<br/>\n       - Horizontal forces on the curved walls cancel each other symmetrically.<br/>\n    4. Since the fluid element is in static equilibrium, the net vertical force is zero:\n    \\sum F_y = 0 &rArr; F_2 - F_1 - W = 0\n    P_2 A - P_1 A - &rho; A h g = 0\n    Dividing both sides by area A:\n    P_2 - P_1 = &rho; g h\n    5. If the top face is chosen at the open free liquid surface where pressure is atmospheric pressure (P_1 = P_0), then the absolute pressure P at depth h is:\n    \\mathbf{P = P_0 + &rho; g h}\n    <b style=\"color: #FF007F;\">Gauge Pressure:</b> The excess pressure above atmospheric pressure is called <strong>gauge pressure</strong>:\n    P_g = P - P_0 = &rho; g h\n    <b style=\"color: #FF007F;\">Hydrostatic Paradox:</b><br/>\n    Consider vessels of completely different shapes (cylindrical, conical, flask-like) having identical bottom base areas A and filled with liquid to the identical vertical depth h. Although the total weight of liquid in each vessel is vastly different, the liquid pressure at the base depends <strong>only on vertical depth h</strong> (P = P_0 + &rho; g h) and is independent of vessel shape or total liquid volume.<br/>\n    Thus, the downward force exerted on the base (F = P &middot; A) is identical in all vessels. The difference between the liquid weight and the bottom force is supported by the vertical components of the reaction forces exerted by the sloping container walls.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q85: Dimensional Derivation of Stokes' Law and Terminal Velocity</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Using dimensional analysis, derive Stokes' Law for the viscous drag force on a smooth spherical body of radius r moving with velocity v through a fluid of coefficient of viscosity &eta;. Hence, derive the complete formula for the terminal velocity of the sphere falling through the fluid.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Part 1: Dimensional Derivation of Stokes' Law:</b><br/>\n    Assume the viscous drag force F_v depends on: (i) coefficient of viscosity &eta;<sup>a</sup>, (ii) radius of sphere r<sup>b</sup>, and (iii) velocity v<sup>c</sup>:\n    F_v = k &eta;<sup>a</sup> r<sup>b</sup> v<sup>c</sup>\n    Dimensions of the quantities:<br/>\n    [F_v] = [M<sup>1</sup> L<sup>1</sup> T<sup>-2</sup>]<br/>\n    [&eta;] = [M<sup>1</sup> L<sup>-1</sup> T<sup>-1</sup>]<br/>\n    [r] = [L<sup>1</sup>]<br/>\n    [v] = [L<sup>1</sup> T<sup>-1</sup>]<br/>\n    Equating dimensions on both sides:\n    [M<sup>1</sup> L<sup>1</sup> T<sup>-2</sup>] = [M<sup>1</sup> L<sup>-1</sup> T<sup>-1</sup>]<sup>a</sup> [L<sup>1</sup>]<sup>b</sup> [L<sup>1</sup> T<sup>-1</sup>]<sup>c</sup> = [M<sup>a</sup> L<sup>-a + b + c</sup> T<sup>-a - c</sup>]\n    Comparing exponents of fundamental units:<br/>\n    For M: a = 1<br/>\n    For T: -a - c = -2 &rArr; -1 - c = -2 &rArr; c = 1<br/>\n    For L: -a + b + c = 1 &rArr; -1 + b + 1 = 1 &rArr; b = 1<br/>\n    Experimentally, Stokes determined the dimensionless proportionality constant k = 6&pi;.<br/>\n    Therefore, <strong>Stokes' Law</strong> is:\n    \\mathbf{F_v = 6&pi; &eta; r v}\n    <b style=\"color: #FF007F;\">Part 2: Terminal Velocity Derivation:</b><br/>\n    Consider a sphere of radius r and density &rho; falling vertically through an extensive fluid medium of density &sigma; and viscosity &eta;.<br/>\n    Three forces act on the sphere:<br/>\n    1. Downward gravitational weight:\n    W = m g = ((4 / 3)&pi; r<sup>3</sup>&rho;) g\n    2. Upward buoyant force (Archimedes' principle):\n    F_b = ((4 / 3)&pi; r<sup>3</sup>&sigma;) g\n    3. Upward viscous retarding force:\n    F_v = 6&pi; &eta; r v\n    As velocity increases, F_v increases until net force becomes zero (sum F = 0), and the sphere attains a constant maximum velocity called <strong>terminal velocity</strong> (v_t):\n    W = F_b + F_v\n    (4 / 3)&pi; r<sup>3</sup>&rho; g = (4 / 3)&pi; r<sup>3</sup>&sigma; g + 6&pi; &eta; r v_t\n    6&pi; &eta; r v_t = (4 / 3)&pi; r<sup>3</sup>(&rho; - &sigma;) g\n    Dividing both sides by 6&pi; &eta; r:\n    \\mathbf{v_t = (2 / 9) {r<sup>2</sup>(&rho; - &sigma;)g}{&eta;}}\n    Note: If &rho; > &sigma; (lead shot in oil), v_t > 0 (sphere falls). If &rho; < &sigma; (air bubble in water), v_t < 0 (bubble rises with terminal speed).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q86: State and Prove the Equation of Continuity for Steady Fluid Flow</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> State the Equation of Continuity for steady streamline flow of an incompressible fluid. Prove it from the principle of conservation of mass for flow through a non-uniform pipe. Discuss its physical implications.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Statement:</b> For steady, streamline, non-viscous flow of an incompressible fluid through a pipe of varying cross-section, the product of cross-sectional area A and fluid flow speed v remains constant at every point along the streamline:\n    A &middot; v = constant \\quad or \\quad A_1 v_1 = A_2 v_2\n    <b style=\"color: #FF007F;\">Proof:</b><br/>\n    1. Consider an incompressible fluid of uniform density &rho; undergoing steady streamline flow through a tube of non-uniform cross-section.<br/>\n    2. Let cross-sectional area, fluid velocity, and density at section 1 be A_1, v_1, \\rho_1 and at section 2 be A_2, v_2, \\rho_2.<br/>\n    3. In a small time interval &Delta;t:<br/>\n       - Fluid entering section 1 travels a distance &Delta;x_1 = v_1 &Delta;t.<br/>\n       - Volume of fluid entering: &Delta;V_1 = A_1 &Delta;x_1 = A_1 v_1 &Delta;t.<br/>\n       - Mass of fluid entering: &Delta;m_1 = \\rho_1 &Delta;V_1 = \\rho_1 A_1 v_1 &Delta;t.<br/>\n       - Similarly, mass of fluid leaving section 2: &Delta;m_2 = \\rho_2 A_2 v_2 &Delta;t.<br/>\n    4. By the <strong>Law of Conservation of Mass</strong>, since fluid is neither created nor destroyed and the flow is steady (no accumulation of fluid inside the pipe):\n    &Delta;m_1 = &Delta;m_2 &rArr; \\rho_1 A_1 v_1 &Delta;t = \\rho_2 A_2 v_2 &Delta;t\n    \\rho_1 A_1 v_1 = \\rho_2 A_2 v_2\n    5. For an <strong>incompressible fluid</strong>, density remains constant everywhere (\\rho_1 = \\rho_2 = &rho;):\n    A_1 v_1 = A_2 v_2 &rArr; \\mathbf{A &middot; v = constant}\n    <b style=\"color: #FF007F;\">Physical Implications:</b><br/>\n    - Since v &prop; 1/A, fluid flows faster through narrow constrictions and slows down in broader regions.<br/>\n    - When water emerges from a household tap, the stream accelerates downward under gravity (v increases), causing its cross-sectional area A to narrow continuously into a sharp tapering jet.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q87: State and Derive Bernoulli's Theorem by Work-Energy Theorem</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> State Bernoulli's theorem for an ideal fluid. State all simplifying assumptions made in its derivation. Prove Bernoulli's equation rigorously by applying the work-energy theorem to a fluid element flowing through an inclined pipe of non-uniform cross-section.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Statement:</b> For the steady, streamline, irrotational flow of an ideal (incompressible and non-viscous) fluid, the total mechanical energy per unit volume—comprising pressure energy, kinetic energy, and gravitational potential energy—remains constant at every point along a streamline:\n    P + (1 / 2)&rho; v<sup>2</sup> + &rho; g h = constant\n    <b style=\"color: #FF007F;\">Assumptions:</b> (i) Incompressible fluid (constant density &rho;), (ii) Non-viscous (zero internal shear friction), (iii) Steady streamline flow, (iv) Irrotational flow.<br/><br/>\n    <b style=\"color: #FF007F;\">Derivation:</b><br/>\n    1. Consider fluid flowing through an inclined tube between section 1 (area A_1, height h_1, pressure P_1, speed v_1) and section 2 (area A_2, height h_2, pressure P_2, speed v_2).<br/>\n    2. In time interval &Delta;t, mass &Delta;m = &rho; &Delta;V = &rho; A_1 v_1 &Delta;t = &rho; A_2 v_2 &Delta;t enters at section 1 and leaves at section 2.<br/>\n    3. <strong>Work done by pressure forces:</strong><br/>\n       - At entrance: Force F_1 = P_1 A_1, displacement &Delta;x_1 = v_1 &Delta;t. Work done ON fluid:\n       W_1 = F_1 &Delta;x_1 = P_1 A_1 v_1 &Delta;t = P_1 &Delta;V\n       - At exit: Force F_2 = P_2 A_2 opposes flow, displacement &Delta;x_2 = v_2 &Delta;t. Work done BY fluid:\n       W_2 = -P_2 A_2 v_2 &Delta;t = -P_2 &Delta;V\n       - Net external work done on fluid element:\n       W_{net} = W_1 + W_2 = (P_1 - P_2)&Delta;V\n    4. <strong>Change in Kinetic Energy:</strong>\n    &Delta;K = (1 / 2)&Delta;m v_2<sup>2</sup> - (1 / 2)&Delta;m v_1<sup>2</sup> = (1 / 2)(&rho; &Delta;V)(v_2<sup>2</sup> - v_1<sup>2</sup>)\n    5. <strong>Change in Potential Energy:</strong>\n    &Delta;U = &Delta;m g h_2 - &Delta;m g h_1 = (&rho; &Delta;V) g (h_2 - h_1)\n    6. By the <strong>Work-Energy Theorem</strong> (W_{net} = &Delta;K + &Delta;U):\n    (P_1 - P_2)&Delta;V = (1 / 2)&rho; &Delta;V (v_2<sup>2</sup> - v_1<sup>2</sup>) + &rho; &Delta;V g (h_2 - h_1)\n    Cancelling common volume factor &Delta;V:\n    P_1 - P_2 = (1 / 2)&rho; v_2<sup>2</sup> - (1 / 2)&rho; v_1<sup>2</sup> + &rho; g h_2 - &rho; g h_1\n    Rearranging terms with subscript 1 on left and subscript 2 on right:\n    \\mathbf{P_1 + (1 / 2)&rho; v_1<sup>2</sup> + &rho; g h_1 = P_2 + (1 / 2)&rho; v_2<sup>2</sup> + &rho; g h_2}\n    Dividing throughout by &rho; g yields the Head Form:\n    (P / &rho; g) + {v<sup>2</sup>}{2g} + h = constant \\quad (Pressure Head + Velocity Head + Datum Head)\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q88: Working Principle and Mathematical Derivation of the Venturimeter</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Describe the construction, working principle, and complete mathematical derivation of a Venturimeter used to measure the rate of flow of an incompressible liquid through a pipe.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Construction:</b> A Venturimeter consists of three parts inserted into a pipeline: (i) a short converging cone, (ii) a narrow cylindrical throat, and (iii) a gradual diverging cone. A differential manometer containing a manometric liquid of density \\rho_m (or vertical piezometer tubes) connects the main inlet pipe to the throat.<br/><br/>\n    <b style=\"color: #FF007F;\">Mathematical Derivation:</b><br/>\n    Let cross-sectional area and fluid speed at inlet (1) be A_1 and v_1, and at throat (2) be A_2 and v_2. The pipe is horizontal (h_1 = h_2).<br/>\n    1. By the <strong>Equation of Continuity</strong>:\n    A_1 v_1 = A_2 v_2 &rArr; v_2 = ((A_1 / A_2)) v_1\n    2. By <strong>Bernoulli's Equation</strong> for a horizontal tube:\n    P_1 + (1 / 2)&rho; v_1<sup>2</sup> = P_2 + (1 / 2)&rho; v_2<sup>2</sup>\n    P_1 - P_2 = (1 / 2)&rho; (v_2<sup>2</sup> - v_1<sup>2</sup>)\n    3. Substituting v_2 = (A_1 / A_2) v_1:\n    P_1 - P_2 = (1 / 2)&rho; [ ((A_1 / A_2))<sup>2</sup> v_1<sup>2</sup> - v_1<sup>2</sup> ] = (1 / 2)&rho; v_1<sup>2</sup> [ {A_1<sup>2</sup> - A_2<sup>2</sup>}{A_2<sup>2</sup>} ]\n    4. The pressure difference is measured by the height difference h in the differential manometer:\n    P_1 - P_2 = (\\rho_m - &rho;) g h \\quad (or  &rho; g h  if using fluid itself)\n    Equating the pressure differences:\n    &rho; g h = (1 / 2)&rho; v_1<sup>2</sup> ( {A_1<sup>2</sup> - A_2<sup>2</sup>}{A_2<sup>2</sup>} )\n    Solving for v_1:\n    v_1<sup>2</sup> = {2gh A_2<sup>2</sup>}{A_1<sup>2</sup> - A_2<sup>2</sup>} &rArr; v_1 = A_2 &radic;{{2gh}{A_1<sup>2</sup> - A_2<sup>2</sup>}}\n    5. The volume discharge rate Q (volume of liquid flowing per second) is:\n    \\mathbf{Q = A_1 v_1 = {A_1 A_2}{&radic;{A_1<sup>2</sup> - A_2<sup>2</sup>}} &radic;(2gh)}\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q89: Derive Torricelli's Law of Efflux and Calculate Horizontal Range</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> State and derive Torricelli's Law of Efflux for a liquid escaping through a small orifice in a tank open to the atmosphere. Find: (i) speed of efflux, (ii) time of flight to hit the ground, and (iii) the condition for maximum horizontal range on the ground.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Derivation:</b><br/>\n    1. Consider a large open tank filled with liquid of density &rho; to a total height H. A small hole of area a is punched at depth h below the free surface (height from bottom is y = H - h).<br/>\n    2. Let top free surface have area A and speed v_1; orifice has area a and efflux speed v_2. Both top surface and hole are open to atmospheric pressure P_0.<br/>\n    3. By continuity, v_1 = (a/A) v_2. Since A &gg; a, v_1 &approx; 0.<br/>\n    4. Applying Bernoulli's equation between top surface (height H) and orifice (height H - h):\n    P_0 + (1 / 2)&rho; v_1<sup>2</sup> + &rho; g H = P_0 + (1 / 2)&rho; v_2<sup>2</sup> + &rho; g (H - h)\n    Setting v_1 &approx; 0:\n    &rho; g H = (1 / 2)&rho; v_2<sup>2</sup> + &rho; g H - &rho; g h &rArr; (1 / 2)&rho; v_2<sup>2</sup> = &rho; g h\n    \\mathbf{v_2 = &radic;(2gh)}\n    This is <strong>Torricelli's Law</strong>: the velocity of efflux is identical to the velocity acquired by a freely falling body dropped from height h.<br/><br/>\n    <b style=\"color: #FF007F;\">Horizontal Range (R):</b><br/>\n    The emerging jet leaves horizontally with speed v = &radic;(2gh) from a height y = H - h above the ground.<br/>\n    - Time of flight: t = &radic;{(2y / g)} = &radic;{(2(H - h) / g)}<br/>\n    - Horizontal range:\n    R = v &middot; t = &radic;(2gh) &times; &radic;{(2(H - h) / g)} = 2&radic;(h(H - h))\n    <b style=\"color: #FF007F;\">Condition for Maximum Range:</b><br/>\n    To maximize R, differentiate f(h) = h(H - h) = Hh - h<sup>2</sup> with respect to h:\n    (df / dh) = H - 2h = 0 &rArr; h = (H / 2)\n    The horizontal range is maximum when the hole is punched at <strong>mid-depth (h = H/2)</strong>.<br/>\n    Maximum horizontal range:\n    R_{\\max} = 2&radic;{((H / 2))(H - (H / 2))} = 2 &times; (H / 2) = H\n    The maximum range equals the total liquid height H.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q90: Dynamic Lift on an Aerofoil and Magnus Effect: Full Comparative Derivation</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Provide a complete physical and mathematical explanation of: (i) Aerodynamic lift on an aeroplane wing (aerofoil), and (ii) Magnus effect on a spinning ball. Show how both phenomena are direct manifestations of Bernoulli's principle and circulation.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Part (i): Aerodynamic Lift on an Aerofoil:</b><br/>\n    1. An aeroplane wing has an asymmetrical cross-section (aerofoil) with a curved upper surface and flat lower surface, inclined at a slight angle of attack &alpha;.<br/>\n    2. As the wing moves forward through air, streamlines above the wing are crowded together, forcing air to accelerate over the curved crest (v_1 > v_2).<br/>\n    3. According to Bernoulli's equation (neglecting small altitude difference &rho; g h across wing thickness):\n    P_1 + (1 / 2)&rho; v_1<sup>2</sup> = P_2 + (1 / 2)&rho; v_2<sup>2</sup>\n    P_2 - P_1 = (1 / 2)&rho; (v_1<sup>2</sup> - v_2<sup>2</sup>)\n    Since v_1 > v_2, the pressure below the wing (P_2) is significantly greater than pressure above (P_1).<br/>\n    4. The net upward aerodynamic lifting force across wing area A is:\n    F_{lift} = (P_2 - P_1) A = (1 / 2)&rho; A (v_1<sup>2</sup> - v_2<sup>2</sup>)\n    When F_{lift} balances the aircraft's total weight Mg, stable flight is sustained.<br/><br/>\n    <b style=\"color: #FF007F;\">Part (ii): Magnus Effect on a Spinning Ball:</b><br/>\n    1. Consider a ball translating forward with velocity v while spinning about a horizontal axis with angular velocity &omega;.<br/>\n    2. Air has viscosity; hence a thin boundary layer of air is dragged into circular rotation (vorticity/circulation \\Gamma) along with the ball's surface.<br/>\n    3. On the upper side of the ball, the rotational surface velocity opposes the oncoming air stream:\n    v_{top} = v - &omega; r\n    4. On the bottom side, the rotational surface velocity is in the same direction as the oncoming air stream:\n    v_{bottom} = v + &omega; r\n    5. By Bernoulli's principle:\n    P_{top} + (1 / 2)&rho; (v - &omega; r)<sup>2</sup> = P_{bottom} + (1 / 2)&rho; (v + &omega; r)<sup>2</sup>\n    P_{top} - P_{bottom} = (1 / 2)&rho; [(v + &omega; r)<sup>2</sup> - (v - &omega; r)<sup>2</sup>] = 2&rho; v &omega; r\n    6. Because P_{top} > P_{bottom}, an upward downward net transverse force acts on the ball (Kutta-Joukowski lift force F = &rho; v \\Gamma), making the ball dive sharply (topspin) or bend sideways (sidespin swing).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q91: Surface Energy and Surface Tension: Proof that W = T &Delta;A</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Define surface tension and surface energy from molecular theory. Prove rigorously that surface tension is numerically and dimensionally equal to the surface energy per unit area (W = T &Delta;A) by considering a movable wire on a U-shaped rectangular wire frame supporting a liquid film.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Molecular Origin:</b> A molecule in the bulk of a liquid is attracted equally in all directions by neighboring molecules, resulting in zero net force. A molecule in the surface layer experiences a net inward attractive force toward the liquid interior. To bring a molecule from the interior to the surface against this inward force, work must be done. This work is stored as potential energy called <strong>surface energy</strong>.<br/><br/>\n    <b style=\"color: #FF007F;\">Derivation (W = T &Delta;A):</b><br/>\n    1. Consider a U-shaped horizontal metal wire frame supporting a thin soap film, with a frictionless movable cross-wire of length l sliding along its arms.<br/>\n    2. Because a liquid film has <strong>two free surfaces</strong> (top and bottom), surface tension exerts an inward contracting force on the movable wire given by:\n    F = T &times; (2l)\n    3. To displace the wire outward slowly by a small distance &Delta;x at constant speed without accelerating, an equal external force F_{ext} = 2 T l must be applied.<br/>\n    4. The work done by this external force is:\n    W = F_{ext} &middot; &Delta;x = (2 T l) &middot; &Delta;x = T &middot; (2 l &Delta;x)\n    5. Here, l &Delta;x is the increase in area of one face of the film. Since the film has two faces, the total increase in surface area is:\n    &Delta;A = 2 l &Delta;x\n    6. Substituting &Delta;A into the work equation:\n    \\mathbf{W = T &middot; &Delta;A} &rArr; \\mathbf{T = (W / &Delta;A)}\n    <b style=\"color: #FF007F;\">Conclusion:</b> Surface tension T equals the work done per unit increase in surface area, which is precisely the <strong>surface energy per unit area</strong>. Both have the same SI unit: N/m = J/m<sup>2</sup> and identical dimensional formula [M<sup>1</sup> L<sup>0</sup> T<sup>-2</sup>].\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q92: Rigorous Derivation of Excess Pressure Inside Drops and Bubbles</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Using the principle of virtual work (surface energy method), derive the mathematical expressions for the excess pressure inside: (i) a spherical liquid drop of radius R, and (ii) a spherical soap bubble of radius R.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Part (i): Excess Pressure Inside a Spherical Liquid Drop:</b><br/>\n    1. Consider a spherical liquid drop of radius R and surface tension T. Let the internal pressure be P_i and external atmospheric pressure be P_o. The excess pressure is &Delta;P = P_i - P_o.<br/>\n    2. Imagine the drop expands radially by an infinitesimal virtual displacement &Delta;R under this excess pressure.<br/>\n    3. Work done by the excess pressure force during expansion:\n    W = Force &times; &Delta;R = (&Delta;P &middot; A) &Delta;R = &Delta;P (4&pi; R<sup>2</sup>) &Delta;R\n    4. Initial surface area of drop: A_1 = 4&pi; R<sup>2</sup>.<br/>\n       Expanded surface area: A_2 = 4&pi; (R + &Delta;R)<sup>2</sup> = 4&pi; (R<sup>2</sup> + 2R&Delta;R + &Delta;R<sup>2</sup>) &approx; 4&pi; R<sup>2</sup> + 8&pi; R &Delta;R.<br/>\n       Increase in surface area:\n       &Delta;A = A_2 - A_1 = 8&pi; R &Delta;R\n    5. Increase in surface energy of the drop:\n    &Delta;U = T &middot; &Delta;A = T (8&pi; R &Delta;R)\n    6. By conservation of energy, work done equals the increase in surface energy (W = &Delta;U):\n    &Delta;P (4&pi; R<sup>2</sup>) &Delta;R = T (8&pi; R &Delta;R)\n    \\mathbf{&Delta;P_{drop} = (2T / R)}\n    <b style=\"color: #FF007F;\">Part (ii): Excess Pressure Inside a Spherical Soap Bubble:</b><br/>\n    1. A soap bubble has <strong>two free surfaces</strong> (inner air-film interface and outer film-air interface).<br/>\n    2. Total increase in surface area during expansion by &Delta;R:\n    &Delta;A_{total} = 2 &times; (8&pi; R &Delta;R) = 16&pi; R &Delta;R\n    3. Increase in surface energy:\n    &Delta;U = T &middot; &Delta;A_{total} = 16&pi; R T &Delta;R\n    4. Equating work done W = &Delta;P (4&pi; R<sup>2</sup>) &Delta;R to &Delta;U:\n    &Delta;P (4&pi; R<sup>2</sup>) &Delta;R = 16&pi; R T &Delta;R\n    \\mathbf{&Delta;P_{bubble} = (4T / R)}\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q93: Angle of Contact and Derivation of Capillary Ascent Formula (Ascent Formula)</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> What is meant by angle of contact? Explain why the meniscus of water in glass is concave while that of mercury in glass is convex. Derive the capillary ascent formula (h = (2T\\cos&theta; / r&rho; g)) using the balance of forces method.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Angle of Contact (&theta;):</b> The angle enclosed between the tangent drawn to the liquid surface at the point of contact and the solid surface inside the liquid is called the <strong>angle of contact</strong>.<br/>\n    - If adhesive force (F_a) between liquid and solid exceeds cohesive force (F_c / &radic;(2)), the resultant force pulls toward the solid; the liquid wets the solid, forming a <strong>concave meniscus</strong> with an acute angle &theta; < 90<sup>&deg;</sup> (e.g., water in glass, &theta; &approx; 0<sup>&deg;</sup>).<br/>\n    - If cohesive force dominates (F_c / &radic;(2) > F_a), the liquid does not wet the solid, forming a <strong>convex meniscus</strong> with an obtuse angle &theta; > 90<sup>&deg;</sup> (e.g., mercury in glass, &theta; &approx; 138<sup>&deg;</sup>).<br/><br/>\n    <b style=\"color: #FF007F;\">Derivation of Capillary Ascent Formula:</b><br/>\n    1. Consider a clean glass capillary tube of internal bore radius r dipped vertically into water of density &rho; and surface tension T. Water wets the glass (&theta; < 90<sup>&deg;</sup>) and rises to equilibrium height h.<br/>\n    2. At the line of contact along the inner circular circumference of the tube (L = 2&pi; r), surface tension T acts tangential to the liquid meniscus at angle &theta; to the vertical glass wall.<br/>\n    3. Resolving surface tension force into components:<br/>\n       - Horizontal radial components (T \\sin&theta;) act outward symmetrically in all directions around the circle and cancel each other completely.<br/>\n       - Vertical upward components (T \\cos&theta;) add up along the entire circumference of length 2&pi; r:\n       F_{up} = (T \\cos&theta;) &times; (2&pi; r) = 2&pi; r T \\cos&theta;\n    4. This upward force supports the downward gravitational weight of the elevated liquid column of height h (neglecting the tiny volume in the curved meniscus):\n    W = m g = (Volume &times; &rho;) g = (&pi; r<sup>2</sup> h &rho;) g\n    5. In static equilibrium, upward force equals downward weight:\n    F_{up} = W &rArr; 2&pi; r T \\cos&theta; = &pi; r<sup>2</sup> h &rho; g\n    Dividing both sides by &pi; r:\n    2 T \\cos&theta; = r h &rho; g\n    \\mathbf{h = (2T\\cos&theta; / r&rho; g)}\n    This is the celebrated <strong>Ascent Formula</strong>. It proves Jurin's Law (h &prop; 1/r): liquid rises higher in narrower capillaries.\n  </div>\n</div>\n\n<!-- THERMAL LA DERIVATIONS (Q94 to Q100) -->\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q94: Thermal Expansion: Definitions and Exact Proof that &alpha; : &beta; : &gamma; = 1 : 2 : 3</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Define the coefficients of linear expansion (&alpha;), superficial expansion (&beta;), and cubical expansion (&gamma;) of an isotropic solid. Derive mathematically the exact relations connecting them, and prove that &alpha; : &beta; : &gamma; = 1 : 2 : 3.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Definitions:</b><br/>\n    1. <strong>Coefficient of Linear Expansion (&alpha;):</strong> Fractional increase in length per degree rise in temperature:\n    &alpha; = (&Delta;L / L_0 &Delta;T) &rArr; L = L_0 (1 + &alpha; &Delta;T)\n    2. <strong>Coefficient of Superficial Expansion (&beta;):</strong> Fractional increase in area per degree rise in temperature:\n    &beta; = (&Delta;A / A_0 &Delta;T) &rArr; A = A_0 (1 + &beta; &Delta;T)\n    3. <strong>Coefficient of Cubical Expansion (&gamma;):</strong> Fractional increase in volume per degree rise in temperature:\n    &gamma; = (&Delta;V / V_0 &Delta;T) &rArr; V = V_0 (1 + &gamma; &Delta;T)\n    All three have the SI unit K<sup>-1</sup> (or <sup>&deg;</sup>C<sup>-1</sup>).<br/><br/>\n    <b style=\"color: #FF007F;\">Proof of &beta; = 2&alpha;:</b><br/>\n    Consider an isotropic square sheet of side L_0 and initial area A_0 = L_0<sup>2</sup>.<br/>\n    Upon heating by &Delta;T, new side is L = L_0(1 + &alpha; &Delta;T).<br/>\n    New area:\n    A = L<sup>2</sup> = L_0<sup>2</sup>(1 + &alpha; &Delta;T)<sup>2</sup> = A_0 (1 + 2&alpha; &Delta;T + &alpha;<sup>2</sup>&Delta;T<sup>2</sup>)\n    Since &alpha; &approx; 10<sup>-5</sup> K<sup>-1</sup>, the term &alpha;<sup>2</sup>&Delta;T<sup>2</sup> &ll; 1 and is neglected:\n    A &approx; A_0 (1 + 2&alpha; &Delta;T)\n    Comparing with A = A_0 (1 + &beta; &Delta;T) gives:\n    \\mathbf{&beta; = 2&alpha;}\n    <b style=\"color: #FF007F;\">Proof of &gamma; = 3&alpha;:</b><br/>\n    Consider a cube of side L_0 and initial volume V_0 = L_0<sup>3</sup>.<br/>\n    Upon heating by &Delta;T, new volume is:\n    V = L<sup>3</sup> = L_0<sup>3</sup>(1 + &alpha; &Delta;T)<sup>3</sup> = V_0 (1 + 3&alpha; &Delta;T + 3&alpha;<sup>2</sup>&Delta;T<sup>2</sup> + &alpha;<sup>3</sup>&Delta;T<sup>3</sup>)\n    Neglecting higher powers of &alpha;:\n    V &approx; V_0 (1 + 3&alpha; &Delta;T)\n    Comparing with V = V_0 (1 + &gamma; &Delta;T) gives:\n    \\mathbf{&gamma; = 3&alpha;}\n    <b style=\"color: #FF007F;\">Conclusion:</b>\n    &alpha; : &beta; : &gamma; = &alpha; : 2&alpha; : 3&alpha; = \\mathbf{1 : 2 : 3}\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q95: Anomalous Expansion of Water, Hope's Apparatus, and Aquatic Ecology</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Discuss the anomalous expansion of water between 0<sup>&deg;</sup>C and 4<sup>&deg;</sup>C. Describe Hope's experiment and explain why ponds and lakes freeze from top to bottom during severe winters, preserving aquatic flora and fauna.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Anomalous Expansion:</b><br/>\n    When water at 0<sup>&deg;</sup>C is heated, its volume contracts up to 4<sup>&deg;</sup>C, reaching a minimum volume and a <strong>maximum density of 1000 kg/m<sup>3</sup> at 4<sup>&deg;</sup>C</strong>. Above 4<sup>&deg;</sup>C, water expands normally like other liquids.<br/><br/>\n    <b style=\"color: #FF007F;\">Hope's Apparatus Demonstration:</b><br/>\n    1. Hope's apparatus consists of a tall metal cylinder of water fitted with two thermometers: T_1 at the top and T_2 at the bottom. A central trough contains a freezing mixture of ice and salt.<br/>\n    2. As water in the central region cools toward 4<sup>&deg;</sup>C, its density increases. This heavy water sinks to the bottom, causing the lower thermometer T_2 to rapidly drop to 4<sup>&deg;</sup>C.<br/>\n    3. On further cooling below 4<sup>&deg;</sup>C, the water becomes lighter (density decreases). This cold water floats to the top, causing the upper thermometer T_1 to fall to 0<sup>&deg;</sup>C and form ice at the surface, while the bottom thermometer T_2 remains steady at 4<sup>&deg;</sup>C.<br/><br/>\n    <b style=\"color: #FF007F;\">Preservation of Aquatic Life in Winter:</b><br/>\n    1. In severe winter, atmospheric air above a lake cools toward 0<sup>&deg;</sup>C.<br/>\n    2. Surface water cools to 4<sup>&deg;</sup>C, becomes maximally dense, and sinks to the lake bed. Convection continues until the entire lake water reaches 4<sup>&deg;</sup>C.<br/>\n    3. As surface water cools further from 4<sup>&deg;</sup>C to 0<sup>&deg;</sup>C, it becomes less dense and stays at the surface.<br/>\n    4. At 0<sup>&deg;</sup>C, surface water freezes into a blanket of ice. Because ice and water are poor conductors of heat, the thick ice sheet insulates the underlying water from the freezing air.<br/>\n    5. The bottom water remains stable at 4<sup>&deg;</sup>C, allowing fish, plants, and aquatic ecosystems to survive comfortably beneath the frozen lake surface.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q96: Molar Specific Heat Capacities of Gases: Mayer's Relation (C_p - C_v = R)</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Explain why the molar specific heat of a gas at constant pressure (C_p) is always greater than that at constant volume (C_v). Derive Mayer's relation (C_p - C_v = R) using the First Law of Thermodynamics for an ideal gas.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Physical Reason why C_p > C_v:</b><br/>\n    - When 1 mole of gas is heated at <strong>constant volume</strong> (C_v), no mechanical expansion work is done (W = P &Delta;V = 0). All supplied heat energy is utilized solely to raise the internal thermal kinetic energy of the gas molecules (&Delta;Q = &Delta;U).<br/>\n    - When 1 mole of gas is heated at <strong>constant pressure</strong> (C_p), the gas expands against external pressure. The supplied heat must not only increase the internal energy by &Delta;U (to produce the same temperature rise &Delta;T), but must also supply external work (W = P &Delta;V) during expansion.<br/>\n    - Therefore, more heat is required at constant pressure than at constant volume for the same temperature rise: C_p > C_v.<br/><br/>\n    <b style=\"color: #FF007F;\">Derivation of Mayer's Relation:</b><br/>\n    Consider 1 mole of an ideal gas.<br/>\n    1. By the <strong>First Law of Thermodynamics</strong>:\n    dQ = dU + dW = dU + P dV\n    2. If the gas is heated at constant volume (dV = 0) through temperature rise dT:\n    dQ_v = C_v dT &rArr; dU = C_v dT\n    Since internal energy of an ideal gas depends solely on temperature (Joule's law), dU = C_v dT holds true for any process.<br/>\n    3. If the same 1 mole of gas is heated at constant pressure (P = constant) through the same temperature rise dT:\n    dQ_p = C_p dT\n    From First Law:\n    C_p dT = dU + P dV = C_v dT + P dV\n    (C_p - C_v) dT = P dV\n    4. For 1 mole of an ideal gas, the equation of state is:\n    P V = R T\n    Differentiating at constant pressure P:\n    P dV = R dT\n    5. Substituting P dV = R dT into the thermodynamic equation:\n    (C_p - C_v) dT = R dT\n    Dividing both sides by dT:\n    \\mathbf{C_p - C_v = R}\n    This is <strong>Mayer's Relation</strong>. If c_p and c_v are principal specific heats (per gram), c_p - c_v = R/M = r.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q97: Principle of Calorimetry and Method of Mixtures for Specific Heat</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> State the Principle of Calorimetry. Describe the method of mixtures used in the laboratory to determine the specific heat capacity of a solid metal cylinder, including heat loss corrections and water equivalent.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Principle of Calorimetry:</b> When two or more bodies at different temperatures are placed in thermal contact inside an insulated system, heat flows from higher-temperature bodies to lower-temperature bodies until thermal equilibrium is attained. In the absence of chemical reactions and heat loss to surroundings:\n    \\mathbf{Heat Lost by Hot Bodies = Heat Gained by Cold Bodies}\n    <b style=\"color: #FF007F;\">Method of Mixtures:</b><br/>\n    1. A solid metal piece of mass m_s and unknown specific heat c_s is heated in a hypsometer to a steady boiling temperature T_1 (e.g., 100<sup>&deg;</sup>C).<br/>\n    2. A copper calorimeter of mass m_c and specific heat c_c contains water of mass m_w (specific heat c_w) at initial room temperature T_2.<br/>\n    3. The hot solid is quickly transferred to the calorimeter, the mixture is gently stirred, and the final maximum equilibrium temperature T is recorded.<br/>\n    4. <strong>Heat Lost by Solid:</strong>\n    Q_{lost} = m_s c_s (T_1 - T)\n    5. <strong>Heat Gained by Water and Calorimeter:</strong>\n    Q_{gained} = m_w c_w (T - T_2) + m_c c_c (T - T_2) = (m_w c_w + m_c c_c)(T - T_2)\n    The term W_e = m_c c_c / c_w is called the <strong>water equivalent</strong> of the calorimeter.<br/>\n    6. Equating heat lost to heat gained:\n    m_s c_s (T_1 - T) = (m_w c_w + m_c c_c)(T - T_2)\n    \\mathbf{c_s = ((m_w c_w + m_c c_c)(T - T_2) / m_s (T_1 - T))}\n    <b style=\"color: #FF007F;\">Radiation Correction:</b> Radiation losses during stirring are corrected using Regnault's cooling correction (Delta T_{corr}) to obtain exact results.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q98: Steady State Heat Conduction: Fourier's Law and Slabs in Series & Parallel</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> State Fourier's Law of thermal conduction. Define coefficient of thermal conductivity and thermal resistance. Derive formulas for the equivalent thermal conductivity and interface temperatures for two slabs of thicknesses d_1, d_2 and conductivities K_1, K_2 placed: (i) in series, and (ii) in parallel.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Fourier's Law:</b> In steady state, the rate of heat flow H = (dQ / dt) conducted normally across a uniform slab of cross-sectional area A and thickness x between faces at temperatures T_1 and T_2 (T_1 > T_2) is:\n    H = (dQ / dt) = K A ((T_1 - T_2 / x)) = -K A (dT / dx)\n    where K is the <strong>coefficient of thermal conductivity</strong> (SI unit: W/m&middot; K).<br/>\n    <b style=\"color: #FF007F;\">Thermal Resistance (R_{th}):</b> In direct analogy with Ohm's Law (I = {&Delta;V}{R_{elec}}):\n    H = {T_1 - T_2}{R_{th}} &rArr; R_{th} = (x / K A)\n    <b style=\"color: #FF007F;\">Part (i): Slabs in Series Thermal Contact:</b><br/>\n    Two slabs of thicknesses d_1, d_2, conductivities K_1, K_2, and equal area A are placed end-to-end.<br/>\n    Total thermal resistance:\n    R_{total} = R_1 + R_2 &rArr; {d_1 + d_2}{K_{eq} A} = (d_1 / K_1 A) + (d_2 / K_2 A)\n    \\mathbf{K_{eq} = (d_1 + d_2 / (d_1 / K_1) + (d_2 / K_2)) = ((d_1 + d_2) K_1 K_2 / d_1 K_2 + d_2 K_1)}\n    If d_1 = d_2 = d: K_{eq} = (2 K_1 K_2 / K_1 + K_2) (Harmonic Mean).<br/><br/>\n    <b style=\"color: #FF007F;\">Part (ii): Slabs in Parallel Thermal Contact:</b><br/>\n    Two slabs of areas A_1, A_2, conductivities K_1, K_2, and equal thickness d are placed side-by-side between common temperature reservoirs T_1 and T_2:<br/>\n    Total heat current H = H_1 + H_2:\n    K_{eq} (A_1 + A_2) (T_1 - T_2 / d) = K_1 A_1 (T_1 - T_2 / d) + K_2 A_2 (T_1 - T_2 / d)\n    \\mathbf{K_{eq} = (K_1 A_1 + K_2 A_2 / A_1 + A_2)}\n    If A_1 = A_2: K_{eq} = (K_1 + K_2 / 2) (Arithmetic Mean).\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q99: Blackbody Radiation, Wien's Displacement Law, and Stefan-Boltzmann Law</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> State and explain: (i) Stefan-Boltzmann Law of radiation, (ii) Wien's Displacement Law, and (iii) Newton's Law of Cooling as a linear approximation of Stefan's Law for small temperature differences.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">1. Stefan-Boltzmann Law:</b><br/>\n    The total radiant energy emitted per second per unit surface area of a blackbody is directly proportional to the fourth power of its absolute thermodynamic temperature T:\n    E = &sigma; T<sup>4</sup>\n    where &sigma; = 5.67 &times; 10<sup>-8</sup> W/m<sup>2</sup>&middot; K<sup>4</sup> is the Stefan-Boltzmann constant.<br/>\n    For a body of emissivity e (0 < e < 1) and surface area A in surroundings at temperature T_0, the net rate of heat loss is:\n    P_{net} = e &sigma; A (T<sup>4</sup> - T_0<sup>4</sup>)\n    <b style=\"color: #FF007F;\">2. Wien's Displacement Law:</b><br/>\n    The wavelength \\lambda_{\\max} corresponding to the maximum emissive power of a blackbody is inversely proportional to its absolute temperature T:\n    \\lambda_{\\max} &middot; T = b = 2.898 &times; 10<sup>-3</sup> m&middot; K\n    As temperature increases, the peak of the emission curve shifts toward shorter wavelengths (from infrared into visible and ultraviolet).<br/><br/>\n    <b style=\"color: #FF007F;\">3. Deduction of Newton's Law of Cooling from Stefan's Law:</b><br/>\n    Let a body at temperature T cool in surroundings at temperature T_0. Let the temperature difference be &Delta;T = T - T_0 &ll; T_0.<br/>\n    Then T = T_0 + &Delta;T = T_0 (1 + &Delta;T / T_0).<br/>\n    By Stefan's Law, radiant heat loss rate is:\n    P = e &sigma; A (T<sup>4</sup> - T_0<sup>4</sup>) = e &sigma; A [ T_0<sup>4</sup>(1 + (&Delta;T / T_0))<sup>4</sup> - T_0<sup>4</sup> ]\n    Using binomial expansion for small &Delta;T / T_0:\n    (1 + (&Delta;T / T_0))<sup>4</sup> &approx; 1 + 4(&Delta;T / T_0)\n    Substituting into the equation:\n    P &approx; e &sigma; A T_0<sup>4</sup> ( 1 + 4(&Delta;T / T_0) - 1 ) = (4 e &sigma; A T_0<sup>3</sup>) &Delta;T\n    Since rate of loss of heat is P = -m c (dT / dt):\n    -m c (dT / dt) = (4 e &sigma; A T_0<sup>3</sup>)(T - T_0) &rArr; -(dT / dt) = K (T - T_0)\n    This proves <strong>Newton's Law of Cooling</strong>: for small temperature differences, the rate of cooling is directly proportional to the temperature excess over surroundings.\n  </div>\n</div>\n\n<div style=\"margin-bottom: 24px;\">\n  <h3 style=\"color: #FF007F; font-size: 16px; margin-bottom: 8px;\">Q100: Master Synthesis of Unit VII: Properties of Bulk Matter (09 Marks)</h3>\n  <p style=\"color: #E2E8F0; margin-bottom: 10px;\"><strong>Question:</strong> Present a master executive synthesis of Unit VII: Properties of Bulk Matter (09 Marks). Provide a high-yield comparative matrix summarizing all fundamental governing laws, core formulas, SI units, and dimensional formulas across Solids, Fluids, and Thermal Physics.</p>\n  <div style=\"background: rgba(255,255,255,0.03); padding: 12px 14px; border-left: 3px solid #FF007F; border-radius: 4px; color: #CBD5E1; line-height: 1.6;\">\n    <strong>Answer:</strong><br/>\n    <b style=\"color: #FF007F;\">Comprehensive Executive Matrix of Unit VII:</b><br/><br/>\n    <div style=\"overflow-x: auto;\">\n      <table style=\"width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 13px;\">\n        <thead>\n          <tr style=\"background: rgba(255, 0, 127, 0.15); border-bottom: 2px solid #FF007F;\">\n            <th style=\"padding: 8px; text-align: left; color: #FF007F; border: 1px solid rgba(255,255,255,0.1);\">Branch</th>\n            <th style=\"padding: 8px; text-align: left; color: #FF007F; border: 1px solid rgba(255,255,255,0.1);\">Governing Law / Concept</th>\n            <th style=\"padding: 8px; text-align: left; color: #FF007F; border: 1px solid rgba(255,255,255,0.1);\">Master Formula</th>\n            <th style=\"padding: 8px; text-align: left; color: #FF007F; border: 1px solid rgba(255,255,255,0.1);\">SI Unit & Dimensions</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1); font-weight: bold; color: #F1F5F9;\">Solids</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Hooke's Law & Moduli (Y, B, G)</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Y = (F L / A &Delta;L),\\; B = -(&Delta;P / &Delta;V/V),\\; G = (F / A&theta;)</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">N/m<sup>2</sup> (Pa), [M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</td>\n          </tr>\n          <tr style=\"background: rgba(255,255,255,0.02);\">\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1); font-weight: bold; color: #F1F5F9;\">Solids</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Elastic Potential Energy Density</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">u = (1 / 2) &times; stress &times; strain = (1 / 2) Y \\epsilon<sup>2</sup></td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">J/m<sup>3</sup> (Pa), [M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</td>\n          </tr>\n          <tr>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1); font-weight: bold; color: #F1F5F9;\">Solids</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Poisson's Ratio (&sigma;)</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">&sigma; = -(&Delta;D / D / &Delta;L / L) (Practical: 0.2 - 0.4)</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Dimensionless, [M<sup>0</sup> L<sup>0</sup> T<sup>0</sup>]</td>\n          </tr>\n          <tr style=\"background: rgba(255,255,255,0.02);\">\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1); font-weight: bold; color: #F1F5F9;\">Fluids</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Hydrostatic Pressure at Depth</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">P = P_0 + &rho; g h</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Pa (N/m<sup>2</sup>), [M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</td>\n          </tr>\n          <tr>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1); font-weight: bold; color: #F1F5F9;\">Fluids</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Stokes' Law & Terminal Velocity</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">F_v = 6&pi; &eta; r v,\\; v_t = (2 / 9){r<sup>2</sup>(&rho;-&sigma;)g}{&eta;}</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">&eta;: Pa&middot; s, [M<sup>1</sup> L<sup>-1</sup> T<sup>-1</sup>]</td>\n          </tr>\n          <tr style=\"background: rgba(255,255,255,0.02);\">\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1); font-weight: bold; color: #F1F5F9;\">Fluids</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Continuity & Bernoulli's Theorem</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">A_1 v_1 = A_2 v_2,\\; P + (1 / 2)&rho; v<sup>2</sup> + &rho; g h = const</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">J/m<sup>3</sup> (Pa), [M<sup>1</sup> L<sup>-1</sup> T<sup>-2</sup>]</td>\n          </tr>\n          <tr>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1); font-weight: bold; color: #F1F5F9;\">Fluids</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Surface Tension & Capillary Rise</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">&Delta;P_{drop} = (2T / R),\\; &Delta;P_{bubble} = (4T / R),\\; h = (2T\\cos&theta; / r&rho; g)</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">T: N/m, [M<sup>1</sup> L<sup>0</sup> T<sup>-2</sup>]</td>\n          </tr>\n          <tr style=\"background: rgba(255,255,255,0.02);\">\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1); font-weight: bold; color: #F1F5F9;\">Thermal</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Thermal Expansion Relations</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">&beta; = 2&alpha;,\\; &gamma; = 3&alpha; &rArr; &alpha; : &beta; : &gamma; = 1 : 2 : 3</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">K<sup>-1</sup>, [K<sup>-1</sup>]</td>\n          </tr>\n          <tr>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1); font-weight: bold; color: #F1F5F9;\">Thermal</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Mayer's Formula & Calorimetry</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">C_p - C_v = R,\\; Q = m c &Delta;T + m L</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">c: J/kg&middot; K, [L<sup>2</sup> T<sup>-2</sup> K<sup>-1</sup>]</td>\n          </tr>\n          <tr style=\"background: rgba(255,255,255,0.02);\">\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1); font-weight: bold; color: #F1F5F9;\">Thermal</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">Fourier Conduction & Radiation</td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">H = (K A &Delta;T / x),\\; \\lambda_{\\max} T = b,\\; E = &sigma; T<sup>4</sup></td>\n            <td style=\"padding: 8px; border: 1px solid rgba(255,255,255,0.1);\">K: W/m&middot; K, [M<sup>1</sup> L<sup>1</sup> T<sup>-3</sup> K<sup>-1</sup>]$</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n</div>\n\n</div>\n";

